INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('54a2c0ef-b733-55b0-bb94-7a5d27068e67', NULL, 'Classroom Words', 'Identify essential classroom people and objects.

The learner uses English in a realistic study situation focused on classroom words.', 5, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"This is a book.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["This is a book.","That is the board.","She is my classmate."],"points":10,"prompt":"Which phrase best helps you: identify essential classroom people and objects.","type":"multiple_choice"},{"answer":["This is a book.","That is the board.","She is my classmate."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["This is a book.","That is the board.","She is my classmate."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Name five things in the classroom.","type":"recording"}],"final_task":{"learner_instruction":"Name five things in the classroom. Speak for at least 45 seconds.","minimum_seconds":45,"required_language":["This is a book.","That is the board."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Name five things in the classroom.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T01_L06","lesson_number":6,"mission":"Identify essential classroom people and objects.","objectives":["Use key words and phrases to identify essential classroom people and objects.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on classroom words.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to identify essential classroom people and objects.","examples":["This is a book.","That is the board.","She is my classmate."],"pattern":"this/that + be","point":"this/that + be"}],"phrases":[{"audio_key":"a1_study_t01_l06_phrase_01","example":"This is a book.","formality":"neutral","phrase":"This is a book.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l06_phrase_02","example":"That is the board.","formality":"neutral","phrase":"That is the board.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t01_l06_phrase_03","example":"She is my classmate.","formality":"neutral","phrase":"She is my classmate.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t01_l06_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear names, greetings, and final consonants.","model":"This is a book.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t01_l06_vocab_01","example":"I use the word ''book'' in this lesson.","image_key":"a1_study_t01_l06_vocab_01","meaning":"A key word used in this lesson: book.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''book''.","word":"book"},{"audio_key":"a1_study_t01_l06_vocab_02","example":"I use the word ''pen'' in this lesson.","image_key":"a1_study_t01_l06_vocab_02","meaning":"A key word used in this lesson: pen.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''pen''.","word":"pen"},{"audio_key":"a1_study_t01_l06_vocab_03","example":"I use the word ''desk'' in this lesson.","image_key":"a1_study_t01_l06_vocab_03","meaning":"A key word used in this lesson: desk.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''desk''.","word":"desk"},{"audio_key":"a1_study_t01_l06_vocab_04","example":"I use the word ''board'' in this lesson.","image_key":"a1_study_t01_l06_vocab_04","meaning":"A key word used in this lesson: board.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''board''.","word":"board"},{"audio_key":"a1_study_t01_l06_vocab_05","example":"I use the word ''classmate'' in this lesson.","image_key":"a1_study_t01_l06_vocab_05","meaning":"A key word used in this lesson: classmate.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''classmate''.","word":"classmate"}]},"title":"Classroom Words"}'::jsonb, NOW(), NOW())
