INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('392ba929-5365-57a2-ba16-28faa5a7c6c1', NULL, 'Whose Book Is This?', 'Ask who owns an item.

The learner uses English in a realistic study situation focused on whose book is this?.', 5, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Whose book is this?","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Whose book is this?","It is mine.","Is this yours?"],"points":10,"prompt":"Which phrase best helps you: ask who owns an item.","type":"multiple_choice"},{"answer":["Whose book is this?","It is mine.","Is this yours?"],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Whose book is this?","It is mine.","Is this yours?"],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Return three items to their owners.","type":"recording"}],"final_task":{"learner_instruction":"Return three items to their owners. Speak for at least 45 seconds.","minimum_seconds":45,"required_language":["Whose book is this?","It is mine."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Return three items to their owners.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T02_L06","lesson_number":6,"mission":"Ask who owns an item.","objectives":["Use key words and phrases to ask who owns an item.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on whose book is this?.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to ask who owns an item.","examples":["Whose book is this?","It is mine.","Is this yours?"],"pattern":"possessive pronouns","point":"possessive pronouns"}],"phrases":[{"audio_key":"a1_study_t02_l06_phrase_01","example":"Whose book is this?","formality":"neutral","phrase":"Whose book is this?","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t02_l06_phrase_02","example":"It is mine.","formality":"neutral","phrase":"It is mine.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t02_l06_phrase_03","example":"Is this yours?","formality":"neutral","phrase":"Is this yours?","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t02_l06_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear plural endings and key classroom words.","model":"Whose book is this?","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t02_l06_vocab_01","example":"I use the word ''mine'' in this lesson.","image_key":"a1_study_t02_l06_vocab_01","meaning":"A key word used in this lesson: mine.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''mine''.","word":"mine"},{"audio_key":"a1_study_t02_l06_vocab_02","example":"I use the word ''yours'' in this lesson.","image_key":"a1_study_t02_l06_vocab_02","meaning":"A key word used in this lesson: yours.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''yours''.","word":"yours"},{"audio_key":"a1_study_t02_l06_vocab_03","example":"I use the word ''his'' in this lesson.","image_key":"a1_study_t02_l06_vocab_03","meaning":"A key word used in this lesson: his.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''his''.","word":"his"},{"audio_key":"a1_study_t02_l06_vocab_04","example":"I use the word ''hers'' in this lesson.","image_key":"a1_study_t02_l06_vocab_04","meaning":"A key word used in this lesson: hers.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''hers''.","word":"hers"},{"audio_key":"a1_study_t02_l06_vocab_05","example":"I use the word ''whose'' in this lesson.","image_key":"a1_study_t02_l06_vocab_05","meaning":"A key word used in this lesson: whose.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''whose''.","word":"whose"}]},"title":"Whose Book Is This?"}'::jsonb, NOW(), NOW())
