INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('04d32371-3089-5ed6-87da-6e4c21c9a46f', NULL, 'Open to Page Ten', 'Follow page and book instructions.

The learner uses English in a realistic study situation focused on open to page ten.', 6, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Open to page ten.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Open to page ten.","Read line two.","Do exercise three."],"points":10,"prompt":"Which phrase best helps you: follow page and book instructions.","type":"multiple_choice"},{"answer":["Open to page ten.","Read line two.","Do exercise three."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Open to page ten.","Read line two.","Do exercise three."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Follow a short sequence of book instructions.","type":"recording"}],"final_task":{"learner_instruction":"Follow a short sequence of book instructions. Speak for at least 50 seconds.","minimum_seconds":50,"required_language":["Open to page ten.","Read line two."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Follow a short sequence of book instructions.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T02_L07","lesson_number":7,"mission":"Follow page and book instructions.","objectives":["Use key words and phrases to follow page and book instructions.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on open to page ten.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to follow page and book instructions.","examples":["Open to page ten.","Read line two.","Do exercise three."],"pattern":"imperatives + numbers","point":"imperatives + numbers"}],"phrases":[{"audio_key":"a1_study_t02_l07_phrase_01","example":"Open to page ten.","formality":"neutral","phrase":"Open to page ten.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t02_l07_phrase_02","example":"Read line two.","formality":"neutral","phrase":"Read line two.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t02_l07_phrase_03","example":"Do exercise three.","formality":"neutral","phrase":"Do exercise three.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t02_l07_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear plural endings and key classroom words.","model":"Open to page ten.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t02_l07_vocab_01","example":"I use the word ''page'' in this lesson.","image_key":"a1_study_t02_l07_vocab_01","meaning":"A key word used in this lesson: page.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''page''.","word":"page"},{"audio_key":"a1_study_t02_l07_vocab_02","example":"I use the word ''chapter'' in this lesson.","image_key":"a1_study_t02_l07_vocab_02","meaning":"A key word used in this lesson: chapter.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''chapter''.","word":"chapter"},{"audio_key":"a1_study_t02_l07_vocab_03","example":"I use the word ''line'' in this lesson.","image_key":"a1_study_t02_l07_vocab_03","meaning":"A key word used in this lesson: line.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''line''.","word":"line"},{"audio_key":"a1_study_t02_l07_vocab_04","example":"I use the word ''exercise'' in this lesson.","image_key":"a1_study_t02_l07_vocab_04","meaning":"A key word used in this lesson: exercise.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''exercise''.","word":"exercise"},{"audio_key":"a1_study_t02_l07_vocab_05","example":"I use the word ''number'' in this lesson.","image_key":"a1_study_t02_l07_vocab_05","meaning":"A key word used in this lesson: number.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''number''.","word":"number"}]},"title":"Open to Page Ten"}'::jsonb, NOW(), NOW())
