VALUES ('b40231a6-df07-50bd-a4ba-7bd1735bfa9e', 'A1_STUDY_T03', 'My School Life', 'A practical A1 track for talking about school places, subjects, schedules, teachers, and favorite classes through short spoken exchanges.', 'en', 'A1', 'thematic', ARRAY['study']::text[], true, 3, '{"package":{"goal":"study","lesson_count":100,"level":"A1","package_id":"A1_STUDY_TRACKS_01_10","recommended_import_order":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"schema_version":"1.0.0","titles":["My First English Class","My Classroom","My School Life","Meeting Friends at School","My Study Day","Asking for Help","Studying Together","School Projects","Tests and Exams","Becoming an Independent Learner"],"track_count":10,"track_ids":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"validation":"All files passed the uploaded JSON Schema using Draft 2020-12."},"track":{"analytics":{"events":["track_started","lesson_started","lesson_completed","speaking_attempted","speaking_passed","mission_attempted","mission_completed","track_completed","track_abandoned"],"mastery_metrics":["pronunciation_accuracy","fluency_score","grammar_accuracy","vocabulary_recall","listening_comprehension","response_relevance","confidence_score","completion_rate"]},"communication_outcome":"The learner can describe their school, name subjects, discuss a simple timetable, and talk about favorite classes.","completion_rules":{"maximum_attempts":null,"minimum_average_score":70,"minimum_lessons_completed":10,"required_final_mission":true,"speaking_pass_score":65},"description":"A practical A1 track for talking about school places, subjects, schedules, teachers, and favorite classes through short spoken exchanges.","difficulty":{"cefr":"A1","speaking_target_seconds":100,"stage":"absolute_beginner","target_words_per_minute":49},"estimated_duration_minutes":120,"goal":"study","language_systems":{"discourse":["short question-answer exchanges","basic turn taking","simple repair strategies","sequencing short ideas"],"functions":["describing school","talking about subjects","asking about schedules","expressing preferences"],"grammar":["Present simple","Have and has","Question words","Days and time expressions"],"pronunciation":[{"description":"Stress in subject names and days of the week.","focus":"word_stress","language_interference_notes":["Use clear English word order.","Do not drop important final consonants.","Avoid adding extra vowel sounds between consonants."]}],"vocabulary":{"core_phrases":["This is the library.","The office is upstairs.","Where is the lab?","I study English.","We have math today.","Do you study science?","English is on Monday.","We have art on Friday.","What do you have today?","What time does class start?","It starts at nine.","It finishes at ten.","My teacher is kind.","She is very helpful.","He teaches science.","My favorite subject is English.","I like it because it is useful.","Math is difficult for me.","I have three lessons today.","Lunch is at twelve."],"target_word_count":50,"themes":["school places","subjects","timetables","teachers","preferences"]}},"learner_identity":"I can talk about my school and my classes.","learning_objectives":[{"can_do_statement":"I can talk about my school and my classes.","measurable_success":"Completes the final speaking mission for My School Life.","objective_id":"OBJ_01","skill":"speaking"},{"can_do_statement":"I can understand short, clear English in this study situation.","measurable_success":"Answers at least 70 percent of listening checks correctly.","objective_id":"OBJ_02","skill":"listening"},{"can_do_statement":"I can use useful words and phrases in a short conversation.","measurable_success":"Uses target language in a multi-turn AI roleplay.","objective_id":"OBJ_03","skill":"interaction"},{"can_do_statement":"I can speak clearly enough for a patient listener to understand me.","measurable_success":"Achieves at least 65 on the speaking rubric.","objective_id":"OBJ_04","skill":"pronunciation"}],"level":"A1","prerequisites":["A1_STUDY_T02"],"progression":{"entry_ability":"The learner has completed the previous A1 Study track or demonstrates equivalent beginner ability.","exit_ability":"The learner can describe their school, name subjects, discuss a simple timetable, and talk about favorite classes.","next_track_unlocks":"A1_STUDY_T04","spiral_review":["Present simple","Have and has","Question words","Days and time expressions","school places","subjects","timetables"]},"rewards":{"badge":{"badge_id":"BADGE_A1_STUDY_T03","description":"Completed the A1 Study track: My School Life.","icon_key":"badge_a1_study_t03","name":"School Life"},"certificate_eligible":false,"unlock_message":"You completed My School Life and can now use English in this study situation.","xp":1000},"schema_version":"1.0.0","short_title":"School Life","title":"My School Life","track_id":"A1_STUDY_T03","track_number":3}}'::jsonb, NOW(), NOW())
