INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('537d0540-d56a-516a-be97-0a594549c8c4', NULL, 'My Teacher', 'Describe a teacher with simple language.

The learner uses English in a realistic study situation focused on my teacher.', 4, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"My teacher is kind.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["My teacher is kind.","She is very helpful.","He teaches science."],"points":10,"prompt":"Which phrase best helps you: describe a teacher with simple language.","type":"multiple_choice"},{"answer":["My teacher is kind.","She is very helpful.","He teaches science."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["My teacher is kind.","She is very helpful.","He teaches science."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Describe one teacher in four sentences.","type":"recording"}],"final_task":{"learner_instruction":"Describe one teacher in four sentences. Speak for at least 40 seconds.","minimum_seconds":40,"required_language":["My teacher is kind.","She is very helpful."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Describe one teacher in four sentences.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T03_L05","lesson_number":5,"mission":"Describe a teacher with simple language.","objectives":["Use key words and phrases to describe a teacher with simple language.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on my teacher.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to describe a teacher with simple language.","examples":["My teacher is kind.","She is very helpful.","He teaches science."],"pattern":"be + adjective; he/she","point":"be + adjective; he/she"}],"phrases":[{"audio_key":"a1_study_t03_l05_phrase_01","example":"My teacher is kind.","formality":"neutral","phrase":"My teacher is kind.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t03_l05_phrase_02","example":"She is very helpful.","formality":"neutral","phrase":"She is very helpful.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t03_l05_phrase_03","example":"He teaches science.","formality":"neutral","phrase":"He teaches science.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t03_l05_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Stress in subject names and days of the week.","model":"My teacher is kind.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t03_l05_vocab_01","example":"I use the word ''kind'' in this lesson.","image_key":"a1_study_t03_l05_vocab_01","meaning":"A key word used in this lesson: kind.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''kind''.","word":"kind"},{"audio_key":"a1_study_t03_l05_vocab_02","example":"I use the word ''helpful'' in this lesson.","image_key":"a1_study_t03_l05_vocab_02","meaning":"A key word used in this lesson: helpful.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''helpful''.","word":"helpful"},{"audio_key":"a1_study_t03_l05_vocab_03","example":"I use the word ''strict'' in this lesson.","image_key":"a1_study_t03_l05_vocab_03","meaning":"A key word used in this lesson: strict.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''strict''.","word":"strict"},{"audio_key":"a1_study_t03_l05_vocab_04","example":"I use the word ''funny'' in this lesson.","image_key":"a1_study_t03_l05_vocab_04","meaning":"A key word used in this lesson: funny.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''funny''.","word":"funny"},{"audio_key":"a1_study_t03_l05_vocab_05","example":"I use the word ''patient'' in this lesson.","image_key":"a1_study_t03_l05_vocab_05","meaning":"A key word used in this lesson: patient.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''patient''.","word":"patient"}]},"title":"My Teacher"}'::jsonb, NOW(), NOW())
