INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('daad7de6-a88f-549d-8f8d-1b1fc5223440', NULL, 'My Favorite Class', 'Say which subject you like and why.

The learner uses English in a realistic study situation focused on my favorite class.', 5, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"My favorite subject is English.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["My favorite subject is English.","I like it because it is useful.","Math is difficult for me."],"points":10,"prompt":"Which phrase best helps you: say which subject you like and why.","type":"multiple_choice"},{"answer":["My favorite subject is English.","I like it because it is useful.","Math is difficult for me."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["My favorite subject is English.","I like it because it is useful.","Math is difficult for me."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Explain your favorite subject.","type":"recording"}],"final_task":{"learner_instruction":"Explain your favorite subject. Speak for at least 45 seconds.","minimum_seconds":45,"required_language":["My favorite subject is English.","I like it because it is useful."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Explain your favorite subject.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T03_L06","lesson_number":6,"mission":"Say which subject you like and why.","objectives":["Use key words and phrases to say which subject you like and why.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on my favorite class.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to say which subject you like and why.","examples":["My favorite subject is English.","I like it because it is useful.","Math is difficult for me."],"pattern":"like + noun; because","point":"like + noun; because"}],"phrases":[{"audio_key":"a1_study_t03_l06_phrase_01","example":"My favorite subject is English.","formality":"neutral","phrase":"My favorite subject is English.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t03_l06_phrase_02","example":"I like it because it is useful.","formality":"neutral","phrase":"I like it because it is useful.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t03_l06_phrase_03","example":"Math is difficult for me.","formality":"neutral","phrase":"Math is difficult for me.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t03_l06_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Stress in subject names and days of the week.","model":"My favorite subject is English.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t03_l06_vocab_01","example":"I use the word ''favorite'' in this lesson.","image_key":"a1_study_t03_l06_vocab_01","meaning":"A key word used in this lesson: favorite.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''favorite''.","word":"favorite"},{"audio_key":"a1_study_t03_l06_vocab_02","example":"I use the word ''easy'' in this lesson.","image_key":"a1_study_t03_l06_vocab_02","meaning":"A key word used in this lesson: easy.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''easy''.","word":"easy"},{"audio_key":"a1_study_t03_l06_vocab_03","example":"I use the word ''difficult'' in this lesson.","image_key":"a1_study_t03_l06_vocab_03","meaning":"A key word used in this lesson: difficult.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''difficult''.","word":"difficult"},{"audio_key":"a1_study_t03_l06_vocab_04","example":"I use the word ''interesting'' in this lesson.","image_key":"a1_study_t03_l06_vocab_04","meaning":"A key word used in this lesson: interesting.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''interesting''.","word":"interesting"},{"audio_key":"a1_study_t03_l06_vocab_05","example":"I use the word ''useful'' in this lesson.","image_key":"a1_study_t03_l06_vocab_05","meaning":"A key word used in this lesson: useful.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''useful''.","word":"useful"}]},"title":"My Favorite Class"}'::jsonb, NOW(), NOW())
