INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('8874c2d2-243d-5151-9a94-2c6093f813e0', NULL, 'My Timetable', 'Describe a simple weekly timetable.

The learner uses English in a realistic study situation focused on my timetable.', 6, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"I have three lessons today.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["I have three lessons today.","Lunch is at twelve.","We have a break at ten."],"points":10,"prompt":"Which phrase best helps you: describe a simple weekly timetable.","type":"multiple_choice"},{"answer":["I have three lessons today.","Lunch is at twelve.","We have a break at ten."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["I have three lessons today.","Lunch is at twelve.","We have a break at ten."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Describe one full school day.","type":"recording"}],"final_task":{"learner_instruction":"Describe one full school day. Speak for at least 50 seconds.","minimum_seconds":50,"required_language":["I have three lessons today.","Lunch is at twelve."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Describe one full school day.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T03_L07","lesson_number":7,"mission":"Describe a simple weekly timetable.","objectives":["Use key words and phrases to describe a simple weekly timetable.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on my timetable.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to describe a simple weekly timetable.","examples":["I have three lessons today.","Lunch is at twelve.","We have a break at ten."],"pattern":"have + schedule","point":"have + schedule"}],"phrases":[{"audio_key":"a1_study_t03_l07_phrase_01","example":"I have three lessons today.","formality":"neutral","phrase":"I have three lessons today.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t03_l07_phrase_02","example":"Lunch is at twelve.","formality":"neutral","phrase":"Lunch is at twelve.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t03_l07_phrase_03","example":"We have a break at ten.","formality":"neutral","phrase":"We have a break at ten.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t03_l07_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Stress in subject names and days of the week.","model":"I have three lessons today.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t03_l07_vocab_01","example":"I use the word ''schedule'' in this lesson.","image_key":"a1_study_t03_l07_vocab_01","meaning":"A key word used in this lesson: schedule.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''schedule''.","word":"schedule"},{"audio_key":"a1_study_t03_l07_vocab_02","example":"I use the word ''lesson'' in this lesson.","image_key":"a1_study_t03_l07_vocab_02","meaning":"A key word used in this lesson: lesson.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''lesson''.","word":"lesson"},{"audio_key":"a1_study_t03_l07_vocab_03","example":"I use the word ''break'' in this lesson.","image_key":"a1_study_t03_l07_vocab_03","meaning":"A key word used in this lesson: break.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''break''.","word":"break"},{"audio_key":"a1_study_t03_l07_vocab_04","example":"I use the word ''lunch'' in this lesson.","image_key":"a1_study_t03_l07_vocab_04","meaning":"A key word used in this lesson: lunch.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''lunch''.","word":"lunch"},{"audio_key":"a1_study_t03_l07_vocab_05","example":"I use the word ''period'' in this lesson.","image_key":"a1_study_t03_l07_vocab_05","meaning":"A key word used in this lesson: period.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''period''.","word":"period"}]},"title":"My Timetable"}'::jsonb, NOW(), NOW())
