INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('d673daa1-c987-5772-83c9-dd7725c32b9d', NULL, 'Before and After Class', 'Talk about activities around class time.

The learner uses English in a realistic study situation focused on before and after class.', 7, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"I arrive before class.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["I arrive before class.","I study after school.","I leave at three."],"points":10,"prompt":"Which phrase best helps you: talk about activities around class time.","type":"multiple_choice"},{"answer":["I arrive before class.","I study after school.","I leave at three."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["I arrive before class.","I study after school.","I leave at three."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Describe what you do before and after class.","type":"recording"}],"final_task":{"learner_instruction":"Describe what you do before and after class. Speak for at least 55 seconds.","minimum_seconds":55,"required_language":["I arrive before class.","I study after school."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Describe what you do before and after class.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T03_L08","lesson_number":8,"mission":"Talk about activities around class time.","objectives":["Use key words and phrases to talk about activities around class time.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on before and after class.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to talk about activities around class time.","examples":["I arrive before class.","I study after school.","I leave at three."],"pattern":"before/after + noun","point":"before/after + noun"}],"phrases":[{"audio_key":"a1_study_t03_l08_phrase_01","example":"I arrive before class.","formality":"neutral","phrase":"I arrive before class.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t03_l08_phrase_02","example":"I study after school.","formality":"neutral","phrase":"I study after school.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t03_l08_phrase_03","example":"I leave at three.","formality":"neutral","phrase":"I leave at three.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t03_l08_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Stress in subject names and days of the week.","model":"I arrive before class.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t03_l08_vocab_01","example":"I use the word ''before'' in this lesson.","image_key":"a1_study_t03_l08_vocab_01","meaning":"A key word used in this lesson: before.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''before''.","word":"before"},{"audio_key":"a1_study_t03_l08_vocab_02","example":"I use the word ''after'' in this lesson.","image_key":"a1_study_t03_l08_vocab_02","meaning":"A key word used in this lesson: after.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''after''.","word":"after"},{"audio_key":"a1_study_t03_l08_vocab_03","example":"I use the word ''arrive'' in this lesson.","image_key":"a1_study_t03_l08_vocab_03","meaning":"A key word used in this lesson: arrive.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''arrive''.","word":"arrive"},{"audio_key":"a1_study_t03_l08_vocab_04","example":"I use the word ''leave'' in this lesson.","image_key":"a1_study_t03_l08_vocab_04","meaning":"A key word used in this lesson: leave.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''leave''.","word":"leave"},{"audio_key":"a1_study_t03_l08_vocab_05","example":"I use the word ''study'' in this lesson.","image_key":"a1_study_t03_l08_vocab_05","meaning":"A key word used in this lesson: study.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''study''.","word":"study"}]},"title":"Before and After Class"}'::jsonb, NOW(), NOW())
