INSERT INTO courses.learning_tracks (id, code, title, description, language, level, track_type, motivation, is_published, sort_order, source_metadata, created_at, updated_at)
VALUES ('04504201-a1b2-53e4-9a40-82642e53b39d', 'A1_STUDY_T04', 'Meeting Friends at School', 'A social communication track that helps A1 learners start conversations, exchange simple personal information, and make plans with classmates.', 'en', 'A1', 'thematic', ARRAY['study']::text[], true, 4, '{"package":{"goal":"study","lesson_count":100,"level":"A1","package_id":"A1_STUDY_TRACKS_01_10","recommended_import_order":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"schema_version":"1.0.0","titles":["My First English Class","My Classroom","My School Life","Meeting Friends at School","My Study Day","Asking for Help","Studying Together","School Projects","Tests and Exams","Becoming an Independent Learner"],"track_count":10,"track_ids":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"validation":"All files passed the uploaded JSON Schema using Draft 2020-12."},"track":{"analytics":{"events":["track_started","lesson_started","lesson_completed","speaking_attempted","speaking_passed","mission_attempted","mission_completed","track_completed","track_abandoned"],"mastery_metrics":["pronunciation_accuracy","fluency_score","grammar_accuracy","vocabulary_recall","listening_comprehension","response_relevance","confidence_score","completion_rate"]},"communication_outcome":"The learner can start a friendly conversation, ask basic personal questions, introduce another person, and exchange contact details.","completion_rules":{"maximum_attempts":null,"minimum_average_score":70,"minimum_lessons_completed":10,"required_final_mission":true,"speaking_pass_score":65},"description":"A social communication track that helps A1 learners start conversations, exchange simple personal information, and make plans with classmates.","difficulty":{"cefr":"A1","speaking_target_seconds":120,"stage":"beginner","target_words_per_minute":51},"estimated_duration_minutes":120,"goal":"study","language_systems":{"discourse":["short question-answer exchanges","basic turn taking","simple repair strategies","sequencing short ideas"],"functions":["starting conversations","asking personal questions","introducing others","exchanging contacts"],"grammar":["Be questions","Present simple questions","Possessive adjectives","Object pronouns"],"pronunciation":[{"description":"Friendly rising and falling intonation in questions and greetings.","focus":"intonation","language_interference_notes":["Use clear English word order.","Do not drop important final consonants.","Avoid adding extra vowel sounds between consonants."]}],"vocabulary":{"core_phrases":["Hi, are you new?","Can I sit here?","How is your day?","How are you?","I am good, thanks.","I am a little nervous.","How old are you?","Where do you live?","What is your hobby?","I like music.","Do you like football?","Yes, I do.","What is your phone number?","My number is...","Send me a message.","This is my friend Ali.","His name is...","She is in my class.","Do you want to join us?","Come with us."],"target_word_count":50,"themes":["friendship","personal information","interests","contact details"]}},"learner_identity":"I can meet classmates and make new friends in English.","learning_objectives":[{"can_do_statement":"I can meet classmates and make new friends in English.","measurable_success":"Completes the final speaking mission for Meeting Friends at School.","objective_id":"OBJ_01","skill":"speaking"},{"can_do_statement":"I can understand short, clear English in this study situation.","measurable_success":"Answers at least 70 percent of listening checks correctly.","objective_id":"OBJ_02","skill":"listening"},{"can_do_statement":"I can use useful words and phrases in a short conversation.","measurable_success":"Uses target language in a multi-turn AI roleplay.","objective_id":"OBJ_03","skill":"interaction"},{"can_do_statement":"I can speak clearly enough for a patient listener to understand me.","measurable_success":"Achieves at least 65 on the speaking rubric.","objective_id":"OBJ_04","skill":"pronunciation"}],"level":"A1","prerequisites":["A1_STUDY_T03"],"progression":{"entry_ability":"The learner has completed the previous A1 Study track or demonstrates equivalent beginner ability.","exit_ability":"The learner can start a friendly conversation, ask basic personal questions, introduce another person, and exchange contact details.","next_track_unlocks":"A1_STUDY_T05","spiral_review":["Be questions","Present simple questions","Possessive adjectives","Object pronouns","friendship","personal information","interests"]},"rewards":{"badge":{"badge_id":"BADGE_A1_STUDY_T04","description":"Completed the A1 Study track: Meeting Friends at School.","icon_key":"badge_a1_study_t04","name":"School Friends"},"certificate_eligible":false,"unlock_message":"You completed Meeting Friends at School and can now use English in this study situation.","xp":1000},"schema_version":"1.0.0","short_title":"School Friends","title":"Meeting Friends at School","track_id":"A1_STUDY_T04","track_number":4}}'::jsonb, NOW(), NOW())
