INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('fef80d66-a215-522e-a8ae-1868b84bf227', NULL, 'This Is My Friend', 'Introduce one classmate to another.

The learner uses English in a realistic study situation focused on this is my friend.', 5, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"This is my friend Ali.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["This is my friend Ali.","His name is...","She is in my class."],"points":10,"prompt":"Which phrase best helps you: introduce one classmate to another.","type":"multiple_choice"},{"answer":["This is my friend Ali.","His name is...","She is in my class."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["This is my friend Ali.","His name is...","She is in my class."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Introduce a friend in three sentences.","type":"recording"}],"final_task":{"learner_instruction":"Introduce a friend in three sentences. Speak for at least 45 seconds.","minimum_seconds":45,"required_language":["This is my friend Ali.","His name is..."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Introduce a friend in three sentences.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T04_L06","lesson_number":6,"mission":"Introduce one classmate to another.","objectives":["Use key words and phrases to introduce one classmate to another.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on this is my friend.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to introduce one classmate to another.","examples":["This is my friend Ali.","His name is...","She is in my class."],"pattern":"possessive adjectives","point":"possessive adjectives"}],"phrases":[{"audio_key":"a1_study_t04_l06_phrase_01","example":"This is my friend Ali.","formality":"neutral","phrase":"This is my friend Ali.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t04_l06_phrase_02","example":"His name is...","formality":"neutral","phrase":"His name is...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t04_l06_phrase_03","example":"She is in my class.","formality":"neutral","phrase":"She is in my class.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t04_l06_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Friendly rising and falling intonation in questions and greetings.","model":"This is my friend Ali.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t04_l06_vocab_01","example":"I use the word ''friend'' in this lesson.","image_key":"a1_study_t04_l06_vocab_01","meaning":"A key word used in this lesson: friend.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''friend''.","word":"friend"},{"audio_key":"a1_study_t04_l06_vocab_02","example":"I use the word ''classmate'' in this lesson.","image_key":"a1_study_t04_l06_vocab_02","meaning":"A key word used in this lesson: classmate.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''classmate''.","word":"classmate"},{"audio_key":"a1_study_t04_l06_vocab_03","example":"I use the word ''meet'' in this lesson.","image_key":"a1_study_t04_l06_vocab_03","meaning":"A key word used in this lesson: meet.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''meet''.","word":"meet"},{"audio_key":"a1_study_t04_l06_vocab_04","example":"I use the word ''his'' in this lesson.","image_key":"a1_study_t04_l06_vocab_04","meaning":"A key word used in this lesson: his.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''his''.","word":"his"},{"audio_key":"a1_study_t04_l06_vocab_05","example":"I use the word ''her'' in this lesson.","image_key":"a1_study_t04_l06_vocab_05","meaning":"A key word used in this lesson: her.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''her''.","word":"her"}]},"title":"This Is My Friend"}'::jsonb, NOW(), NOW())
