INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('6070f6f1-0f53-5043-ac1c-440d19c0a783', NULL, 'Join Us', 'Invite a classmate to join an activity.

The learner uses English in a realistic study situation focused on join us.', 6, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Do you want to join us?","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Do you want to join us?","Come with us.","Let''s study together."],"points":10,"prompt":"Which phrase best helps you: invite a classmate to join an activity.","type":"multiple_choice"},{"answer":["Do you want to join us?","Come with us.","Let''s study together."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Do you want to join us?","Come with us.","Let''s study together."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Invite and respond politely.","type":"recording"}],"final_task":{"learner_instruction":"Invite and respond politely. Speak for at least 50 seconds.","minimum_seconds":50,"required_language":["Do you want to join us?","Come with us."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Invite and respond politely.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T04_L07","lesson_number":7,"mission":"Invite a classmate to join an activity.","objectives":["Use key words and phrases to invite a classmate to join an activity.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on join us.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to invite a classmate to join an activity.","examples":["Do you want to join us?","Come with us.","Let''s study together."],"pattern":"let''s; want to","point":"let''s; want to"}],"phrases":[{"audio_key":"a1_study_t04_l07_phrase_01","example":"Do you want to join us?","formality":"neutral","phrase":"Do you want to join us?","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t04_l07_phrase_02","example":"Come with us.","formality":"neutral","phrase":"Come with us.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t04_l07_phrase_03","example":"Let''s study together.","formality":"neutral","phrase":"Let''s study together.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t04_l07_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Friendly rising and falling intonation in questions and greetings.","model":"Do you want to join us?","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t04_l07_vocab_01","example":"I use the word ''join'' in this lesson.","image_key":"a1_study_t04_l07_vocab_01","meaning":"A key word used in this lesson: join.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''join''.","word":"join"},{"audio_key":"a1_study_t04_l07_vocab_02","example":"I use the word ''come'' in this lesson.","image_key":"a1_study_t04_l07_vocab_02","meaning":"A key word used in this lesson: come.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''come''.","word":"come"},{"audio_key":"a1_study_t04_l07_vocab_03","example":"I use the word ''lunch'' in this lesson.","image_key":"a1_study_t04_l07_vocab_03","meaning":"A key word used in this lesson: lunch.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''lunch''.","word":"lunch"},{"audio_key":"a1_study_t04_l07_vocab_04","example":"I use the word ''study'' in this lesson.","image_key":"a1_study_t04_l07_vocab_04","meaning":"A key word used in this lesson: study.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''study''.","word":"study"},{"audio_key":"a1_study_t04_l07_vocab_05","example":"I use the word ''together'' in this lesson.","image_key":"a1_study_t04_l07_vocab_05","meaning":"A key word used in this lesson: together.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''together''.","word":"together"}]},"title":"Join Us"}'::jsonb, NOW(), NOW())
