VALUES ('62f91e41-eea3-5503-ab48-1bb6c511db14', 'A1_STUDY_T05', 'My Study Day', 'An A1 speaking track for describing daily study routines, telling time, talking about habits, and comparing simple schedules.', 'en', 'A1', 'thematic', ARRAY['study']::text[], true, 5, '{"package":{"goal":"study","lesson_count":100,"level":"A1","package_id":"A1_STUDY_TRACKS_01_10","recommended_import_order":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"schema_version":"1.0.0","titles":["My First English Class","My Classroom","My School Life","Meeting Friends at School","My Study Day","Asking for Help","Studying Together","School Projects","Tests and Exams","Becoming an Independent Learner"],"track_count":10,"track_ids":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"validation":"All files passed the uploaded JSON Schema using Draft 2020-12."},"track":{"analytics":{"events":["track_started","lesson_started","lesson_completed","speaking_attempted","speaking_passed","mission_attempted","mission_completed","track_completed","track_abandoned"],"mastery_metrics":["pronunciation_accuracy","fluency_score","grammar_accuracy","vocabulary_recall","listening_comprehension","response_relevance","confidence_score","completion_rate"]},"communication_outcome":"The learner can describe a typical study day, tell basic times, and ask a classmate about daily routines.","completion_rules":{"maximum_attempts":null,"minimum_average_score":70,"minimum_lessons_completed":10,"required_final_mission":true,"speaking_pass_score":65},"description":"An A1 speaking track for describing daily study routines, telling time, talking about habits, and comparing simple schedules.","difficulty":{"cefr":"A1","speaking_target_seconds":140,"stage":"beginner","target_words_per_minute":53},"estimated_duration_minutes":120,"goal":"study","language_systems":{"discourse":["short question-answer exchanges","basic turn taking","simple repair strategies","sequencing short ideas"],"functions":["describing routines","telling time","asking about habits","sequencing actions"],"grammar":["Present simple","Adverbs of frequency","Time expressions","Do questions"],"pronunciation":[{"description":"Natural rhythm in short present-simple routine sentences.","focus":"rhythm","language_interference_notes":["Use clear English word order.","Do not drop important final consonants.","Avoid adding extra vowel sounds between consonants."]}],"vocabulary":{"core_phrases":["I wake up at seven.","I eat breakfast.","I leave home at eight.","It is eight o''clock.","It is half past nine.","I am late.","I go by bus.","I walk to school.","I arrive at eight thirty.","I listen to the teacher.","We read a text.","I answer questions.","I eat a snack.","I talk with friends.","We go outside.","I do my homework.","I study at the library.","I relax at home.","I always bring my book.","I usually study at night."],"target_word_count":50,"themes":["daily routine","time","study habits","school day"]}},"learner_identity":"I can talk about my daily study routine.","learning_objectives":[{"can_do_statement":"I can talk about my daily study routine.","measurable_success":"Completes the final speaking mission for My Study Day.","objective_id":"OBJ_01","skill":"speaking"},{"can_do_statement":"I can understand short, clear English in this study situation.","measurable_success":"Answers at least 70 percent of listening checks correctly.","objective_id":"OBJ_02","skill":"listening"},{"can_do_statement":"I can use useful words and phrases in a short conversation.","measurable_success":"Uses target language in a multi-turn AI roleplay.","objective_id":"OBJ_03","skill":"interaction"},{"can_do_statement":"I can speak clearly enough for a patient listener to understand me.","measurable_success":"Achieves at least 65 on the speaking rubric.","objective_id":"OBJ_04","skill":"pronunciation"}],"level":"A1","prerequisites":["A1_STUDY_T04"],"progression":{"entry_ability":"The learner has completed the previous A1 Study track or demonstrates equivalent beginner ability.","exit_ability":"The learner can describe a typical study day, tell basic times, and ask a classmate about daily routines.","next_track_unlocks":"A1_STUDY_T06","spiral_review":["Present simple","Adverbs of frequency","Time expressions","Do questions","daily routine","time","study habits"]},"rewards":{"badge":{"badge_id":"BADGE_A1_STUDY_T05","description":"Completed the A1 Study track: My Study Day.","icon_key":"badge_a1_study_t05","name":"My Study Day"},"certificate_eligible":false,"unlock_message":"You completed My Study Day and can now use English in this study situation.","xp":1000},"schema_version":"1.0.0","short_title":"My Study Day","title":"My Study Day","track_id":"A1_STUDY_T05","track_number":5}}'::jsonb, NOW(), NOW())
