INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('8e714b21-315a-5297-899b-a451de177a7a', NULL, 'Always or Sometimes?', 'Use frequency words for study habits.

The learner uses English in a realistic study situation focused on always or sometimes?.', 6, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"I always bring my book.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["I always bring my book.","I usually study at night.","I never miss class."],"points":10,"prompt":"Which phrase best helps you: use frequency words for study habits.","type":"multiple_choice"},{"answer":["I always bring my book.","I usually study at night.","I never miss class."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["I always bring my book.","I usually study at night.","I never miss class."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Describe five habits with frequency.","type":"recording"}],"final_task":{"learner_instruction":"Describe five habits with frequency. Speak for at least 50 seconds.","minimum_seconds":50,"required_language":["I always bring my book.","I usually study at night."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Describe five habits with frequency.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T05_L07","lesson_number":7,"mission":"Use frequency words for study habits.","objectives":["Use key words and phrases to use frequency words for study habits.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on always or sometimes?.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to use frequency words for study habits.","examples":["I always bring my book.","I usually study at night.","I never miss class."],"pattern":"adverbs of frequency","point":"adverbs of frequency"}],"phrases":[{"audio_key":"a1_study_t05_l07_phrase_01","example":"I always bring my book.","formality":"neutral","phrase":"I always bring my book.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t05_l07_phrase_02","example":"I usually study at night.","formality":"neutral","phrase":"I usually study at night.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t05_l07_phrase_03","example":"I never miss class.","formality":"neutral","phrase":"I never miss class.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t05_l07_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Natural rhythm in short present-simple routine sentences.","model":"I always bring my book.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t05_l07_vocab_01","example":"I use the word ''always'' in this lesson.","image_key":"a1_study_t05_l07_vocab_01","meaning":"A key word used in this lesson: always.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''always''.","word":"always"},{"audio_key":"a1_study_t05_l07_vocab_02","example":"I use the word ''usually'' in this lesson.","image_key":"a1_study_t05_l07_vocab_02","meaning":"A key word used in this lesson: usually.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''usually''.","word":"usually"},{"audio_key":"a1_study_t05_l07_vocab_03","example":"I use the word ''sometimes'' in this lesson.","image_key":"a1_study_t05_l07_vocab_03","meaning":"A key word used in this lesson: sometimes.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''sometimes''.","word":"sometimes"},{"audio_key":"a1_study_t05_l07_vocab_04","example":"I use the word ''rarely'' in this lesson.","image_key":"a1_study_t05_l07_vocab_04","meaning":"A key word used in this lesson: rarely.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''rarely''.","word":"rarely"},{"audio_key":"a1_study_t05_l07_vocab_05","example":"I use the word ''never'' in this lesson.","image_key":"a1_study_t05_l07_vocab_05","meaning":"A key word used in this lesson: never.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''never''.","word":"never"}]},"title":"Always or Sometimes?"}'::jsonb, NOW(), NOW())
