INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('70bdade0-bf60-5022-a71c-ba886d30bd66', NULL, 'First, Then, Finally', 'Put daily actions in order.

The learner uses English in a realistic study situation focused on first, then, finally.', 8, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"First, I wake up.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["First, I wake up.","Then, I go to class.","Finally, I go home."],"points":10,"prompt":"Which phrase best helps you: put daily actions in order.","type":"multiple_choice"},{"answer":["First, I wake up.","Then, I go to class.","Finally, I go home."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["First, I wake up.","Then, I go to class.","Finally, I go home."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Tell a routine in clear order.","type":"recording"}],"final_task":{"learner_instruction":"Tell a routine in clear order. Speak for at least 60 seconds.","minimum_seconds":60,"required_language":["First, I wake up.","Then, I go to class."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Tell a routine in clear order.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T05_L09","lesson_number":9,"mission":"Put daily actions in order.","objectives":["Use key words and phrases to put daily actions in order.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on first, then, finally.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to put daily actions in order.","examples":["First, I wake up.","Then, I go to class.","Finally, I go home."],"pattern":"sequencing words","point":"sequencing words"}],"phrases":[{"audio_key":"a1_study_t05_l09_phrase_01","example":"First, I wake up.","formality":"neutral","phrase":"First, I wake up.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t05_l09_phrase_02","example":"Then, I go to class.","formality":"neutral","phrase":"Then, I go to class.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t05_l09_phrase_03","example":"Finally, I go home.","formality":"neutral","phrase":"Finally, I go home.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t05_l09_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Natural rhythm in short present-simple routine sentences.","model":"First, I wake up.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t05_l09_vocab_01","example":"I use the word ''first'' in this lesson.","image_key":"a1_study_t05_l09_vocab_01","meaning":"A key word used in this lesson: first.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''first''.","word":"first"},{"audio_key":"a1_study_t05_l09_vocab_02","example":"I use the word ''then'' in this lesson.","image_key":"a1_study_t05_l09_vocab_02","meaning":"A key word used in this lesson: then.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''then''.","word":"then"},{"audio_key":"a1_study_t05_l09_vocab_03","example":"I use the word ''next'' in this lesson.","image_key":"a1_study_t05_l09_vocab_03","meaning":"A key word used in this lesson: next.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''next''.","word":"next"},{"audio_key":"a1_study_t05_l09_vocab_04","example":"I use the word ''after that'' in this lesson.","image_key":"a1_study_t05_l09_vocab_04","meaning":"A key word used in this lesson: after that.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''after that''.","word":"after that"},{"audio_key":"a1_study_t05_l09_vocab_05","example":"I use the word ''finally'' in this lesson.","image_key":"a1_study_t05_l09_vocab_05","meaning":"A key word used in this lesson: finally.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''finally''.","word":"finally"}]},"title":"First, Then, Finally"}'::jsonb, NOW(), NOW())
