INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('c82b6491-2365-53cc-89eb-a3776c78a088', NULL, 'My Day Mission', 'Speak about a complete study day.

The learner uses English in a realistic study situation focused on my day mission.', 9, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"My day starts at...","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["My day starts at...","I usually...","At the end of the day..."],"points":10,"prompt":"Which phrase best helps you: speak about a complete study day.","type":"multiple_choice"},{"answer":["My day starts at...","I usually...","At the end of the day..."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["My day starts at...","I usually...","At the end of the day..."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Speak for 60 to 90 seconds about your study day.","type":"recording"}],"final_task":{"learner_instruction":"Speak for 60 to 90 seconds about your study day. Speak for at least 65 seconds.","minimum_seconds":65,"required_language":["My day starts at...","I usually..."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Speak for 60 to 90 seconds about your study day.","task_type":"simulation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T05_L10","lesson_number":10,"mission":"Speak about a complete study day.","objectives":["Use key words and phrases to speak about a complete study day.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on my day mission.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to speak about a complete study day.","examples":["My day starts at...","I usually...","At the end of the day..."],"pattern":"integrated review","point":"integrated review"}],"phrases":[{"audio_key":"a1_study_t05_l10_phrase_01","example":"My day starts at...","formality":"neutral","phrase":"My day starts at...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t05_l10_phrase_02","example":"I usually...","formality":"neutral","phrase":"I usually...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t05_l10_phrase_03","example":"At the end of the day...","formality":"neutral","phrase":"At the end of the day...","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t05_l10_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Natural rhythm in short present-simple routine sentences.","model":"My day starts at...","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t05_l10_vocab_01","example":"I use the word ''routine'' in this lesson.","image_key":"a1_study_t05_l10_vocab_01","meaning":"A key word used in this lesson: routine.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''routine''.","word":"routine"},{"audio_key":"a1_study_t05_l10_vocab_02","example":"I use the word ''schedule'' in this lesson.","image_key":"a1_study_t05_l10_vocab_02","meaning":"A key word used in this lesson: schedule.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''schedule''.","word":"schedule"},{"audio_key":"a1_study_t05_l10_vocab_03","example":"I use the word ''habit'' in this lesson.","image_key":"a1_study_t05_l10_vocab_03","meaning":"A key word used in this lesson: habit.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''habit''.","word":"habit"},{"audio_key":"a1_study_t05_l10_vocab_04","example":"I use the word ''time'' in this lesson.","image_key":"a1_study_t05_l10_vocab_04","meaning":"A key word used in this lesson: time.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''time''.","word":"time"},{"audio_key":"a1_study_t05_l10_vocab_05","example":"I use the word ''day'' in this lesson.","image_key":"a1_study_t05_l10_vocab_05","meaning":"A key word used in this lesson: day.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''day''.","word":"day"}]},"title":"My Day Mission"}'::jsonb, NOW(), NOW())
