VALUES ('47e79933-fc3b-57bb-9ba3-f0ce0278011d', 'A1_STUDY_T06', 'Asking for Help', 'A survival communication track for asking teachers and classmates for clarification, repetition, examples, and practical support.', 'en', 'A1', 'thematic', ARRAY['study']::text[], true, 6, '{"package":{"goal":"study","lesson_count":100,"level":"A1","package_id":"A1_STUDY_TRACKS_01_10","recommended_import_order":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"schema_version":"1.0.0","titles":["My First English Class","My Classroom","My School Life","Meeting Friends at School","My Study Day","Asking for Help","Studying Together","School Projects","Tests and Exams","Becoming an Independent Learner"],"track_count":10,"track_ids":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"validation":"All files passed the uploaded JSON Schema using Draft 2020-12."},"track":{"analytics":{"events":["track_started","lesson_started","lesson_completed","speaking_attempted","speaking_passed","mission_attempted","mission_completed","track_completed","track_abandoned"],"mastery_metrics":["pronunciation_accuracy","fluency_score","grammar_accuracy","vocabulary_recall","listening_comprehension","response_relevance","confidence_score","completion_rate"]},"communication_outcome":"The learner can say they do not understand, ask for repetition or explanation, and request simple help politely.","completion_rules":{"maximum_attempts":null,"minimum_average_score":70,"minimum_lessons_completed":10,"required_final_mission":true,"speaking_pass_score":65},"description":"A survival communication track for asking teachers and classmates for clarification, repetition, examples, and practical support.","difficulty":{"cefr":"A1","speaking_target_seconds":160,"stage":"beginner","target_words_per_minute":55},"estimated_duration_minutes":120,"goal":"study","language_systems":{"discourse":["short question-answer exchanges","basic turn taking","simple repair strategies","sequencing short ideas"],"functions":["asking for help","requesting repetition","checking understanding","explaining problems"],"grammar":["Can and could for requests","Imperatives","Object pronouns","Question forms"],"pronunciation":[{"description":"Stress key words in polite requests for help.","focus":"sentence_stress","language_interference_notes":["Use clear English word order.","Do not drop important final consonants.","Avoid adding extra vowel sounds between consonants."]}],"vocabulary":{"core_phrases":["I don''t understand.","What does this mean?","I don''t know this word.","Please say it again.","Can you repeat that?","I didn''t hear you.","Please speak slowly.","Can you say it clearly?","That is too fast.","How do you spell it?","Is that B or D?","Is this correct?","Can you show me?","Can I see an example?","Please do the first one.","Which page?","Which exercise?","Where do I write?","Can you help me?","Can you check this?"],"target_word_count":50,"themes":["clarification","problems","instructions","learning support"]}},"learner_identity":"I can ask for help when learning is difficult.","learning_objectives":[{"can_do_statement":"I can ask for help when learning is difficult.","measurable_success":"Completes the final speaking mission for Asking for Help.","objective_id":"OBJ_01","skill":"speaking"},{"can_do_statement":"I can understand short, clear English in this study situation.","measurable_success":"Answers at least 70 percent of listening checks correctly.","objective_id":"OBJ_02","skill":"listening"},{"can_do_statement":"I can use useful words and phrases in a short conversation.","measurable_success":"Uses target language in a multi-turn AI roleplay.","objective_id":"OBJ_03","skill":"interaction"},{"can_do_statement":"I can speak clearly enough for a patient listener to understand me.","measurable_success":"Achieves at least 65 on the speaking rubric.","objective_id":"OBJ_04","skill":"pronunciation"}],"level":"A1","prerequisites":["A1_STUDY_T05"],"progression":{"entry_ability":"The learner has completed the previous A1 Study track or demonstrates equivalent beginner ability.","exit_ability":"The learner can say they do not understand, ask for repetition or explanation, and request simple help politely.","next_track_unlocks":"A1_STUDY_T07","spiral_review":["Can and could for requests","Imperatives","Object pronouns","Question forms","clarification","problems","instructions"]},"rewards":{"badge":{"badge_id":"BADGE_A1_STUDY_T06","description":"Completed the A1 Study track: Asking for Help.","icon_key":"badge_a1_study_t06","name":"Asking for Help"},"certificate_eligible":false,"unlock_message":"You completed Asking for Help and can now use English in this study situation.","xp":1000},"schema_version":"1.0.0","short_title":"Asking for Help","title":"Asking for Help","track_id":"A1_STUDY_T06","track_number":6}}'::jsonb, NOW(), NOW())
