INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('96ad59c4-a2f5-5164-b798-795e01a59b14', NULL, 'I Don''t Understand', 'Say clearly when you do not understand.

The learner uses English in a realistic study situation focused on i don''t understand.', 0, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"I don''t understand.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["I don''t understand.","What does this mean?","I don''t know this word."],"points":10,"prompt":"Which phrase best helps you: say clearly when you do not understand.","type":"multiple_choice"},{"answer":["I don''t understand.","What does this mean?","I don''t know this word."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["I don''t understand.","What does this mean?","I don''t know this word."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Explain one understanding problem.","type":"recording"}],"final_task":{"learner_instruction":"Explain one understanding problem. Speak for at least 20 seconds.","minimum_seconds":20,"required_language":["I don''t understand.","What does this mean?"],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Explain one understanding problem.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T06_L01","lesson_number":1,"mission":"Say clearly when you do not understand.","objectives":["Use key words and phrases to say clearly when you do not understand.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on i don''t understand.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to say clearly when you do not understand.","examples":["I don''t understand.","What does this mean?","I don''t know this word."],"pattern":"do not + verb","point":"do not + verb"}],"phrases":[{"audio_key":"a1_study_t06_l01_phrase_01","example":"I don''t understand.","formality":"neutral","phrase":"I don''t understand.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t06_l01_phrase_02","example":"What does this mean?","formality":"neutral","phrase":"What does this mean?","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t06_l01_phrase_03","example":"I don''t know this word.","formality":"neutral","phrase":"I don''t know this word.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t06_l01_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Stress key words in polite requests for help.","model":"I don''t understand.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t06_l01_vocab_01","example":"I use the word ''understand'' in this lesson.","image_key":"a1_study_t06_l01_vocab_01","meaning":"A key word used in this lesson: understand.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''understand''.","word":"understand"},{"audio_key":"a1_study_t06_l01_vocab_02","example":"I use the word ''know'' in this lesson.","image_key":"a1_study_t06_l01_vocab_02","meaning":"A key word used in this lesson: know.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''know''.","word":"know"},{"audio_key":"a1_study_t06_l01_vocab_03","example":"I use the word ''mean'' in this lesson.","image_key":"a1_study_t06_l01_vocab_03","meaning":"A key word used in this lesson: mean.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''mean''.","word":"mean"},{"audio_key":"a1_study_t06_l01_vocab_04","example":"I use the word ''word'' in this lesson.","image_key":"a1_study_t06_l01_vocab_04","meaning":"A key word used in this lesson: word.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''word''.","word":"word"},{"audio_key":"a1_study_t06_l01_vocab_05","example":"I use the word ''question'' in this lesson.","image_key":"a1_study_t06_l01_vocab_05","meaning":"A key word used in this lesson: question.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''question''.","word":"question"}]},"title":"I Don''t Understand"}'::jsonb, NOW(), NOW())
