INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('c8296cdb-d3e6-5bbb-9906-2700d8f623d6', NULL, 'Thanking for Help', 'Respond politely after receiving help.

The learner uses English in a realistic study situation focused on thanking for help.', 7, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Thank you for your help.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Thank you for your help.","That is very helpful.","You''re welcome."],"points":10,"prompt":"Which phrase best helps you: respond politely after receiving help.","type":"multiple_choice"},{"answer":["Thank you for your help.","That is very helpful.","You''re welcome."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Thank you for your help.","That is very helpful.","You''re welcome."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Close a help exchange politely.","type":"recording"}],"final_task":{"learner_instruction":"Close a help exchange politely. Speak for at least 55 seconds.","minimum_seconds":55,"required_language":["Thank you for your help.","That is very helpful."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Close a help exchange politely.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T06_L08","lesson_number":8,"mission":"Respond politely after receiving help.","objectives":["Use key words and phrases to respond politely after receiving help.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on thanking for help.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to respond politely after receiving help.","examples":["Thank you for your help.","That is very helpful.","You''re welcome."],"pattern":"thank you for + noun","point":"thank you for + noun"}],"phrases":[{"audio_key":"a1_study_t06_l08_phrase_01","example":"Thank you for your help.","formality":"neutral","phrase":"Thank you for your help.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t06_l08_phrase_02","example":"That is very helpful.","formality":"neutral","phrase":"That is very helpful.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t06_l08_phrase_03","example":"You''re welcome.","formality":"neutral","phrase":"You''re welcome.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t06_l08_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Stress key words in polite requests for help.","model":"Thank you for your help.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t06_l08_vocab_01","example":"I use the word ''thanks'' in this lesson.","image_key":"a1_study_t06_l08_vocab_01","meaning":"A key word used in this lesson: thanks.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''thanks''.","word":"thanks"},{"audio_key":"a1_study_t06_l08_vocab_02","example":"I use the word ''thank'' in this lesson.","image_key":"a1_study_t06_l08_vocab_02","meaning":"A key word used in this lesson: thank.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''thank''.","word":"thank"},{"audio_key":"a1_study_t06_l08_vocab_03","example":"I use the word ''welcome'' in this lesson.","image_key":"a1_study_t06_l08_vocab_03","meaning":"A key word used in this lesson: welcome.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''welcome''.","word":"welcome"},{"audio_key":"a1_study_t06_l08_vocab_04","example":"I use the word ''helpful'' in this lesson.","image_key":"a1_study_t06_l08_vocab_04","meaning":"A key word used in this lesson: helpful.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''helpful''.","word":"helpful"},{"audio_key":"a1_study_t06_l08_vocab_05","example":"I use the word ''kind'' in this lesson.","image_key":"a1_study_t06_l08_vocab_05","meaning":"A key word used in this lesson: kind.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''kind''.","word":"kind"}]},"title":"Thanking for Help"}'::jsonb, NOW(), NOW())
