INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('167024ff-7e8e-57b6-9124-931472b9a124', NULL, 'Solve the Problem', 'Explain a problem and choose the right request.

The learner uses English in a realistic study situation focused on solve the problem.', 8, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"My book is missing.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["My book is missing.","This is difficult.","Can you help me fix it?"],"points":10,"prompt":"Which phrase best helps you: explain a problem and choose the right request.","type":"multiple_choice"},{"answer":["My book is missing.","This is difficult.","Can you help me fix it?"],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["My book is missing.","This is difficult.","Can you help me fix it?"],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Solve three classroom problems.","type":"recording"}],"final_task":{"learner_instruction":"Solve three classroom problems. Speak for at least 60 seconds.","minimum_seconds":60,"required_language":["My book is missing.","This is difficult."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Solve three classroom problems.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T06_L09","lesson_number":9,"mission":"Explain a problem and choose the right request.","objectives":["Use key words and phrases to explain a problem and choose the right request.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on solve the problem.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to explain a problem and choose the right request.","examples":["My book is missing.","This is difficult.","Can you help me fix it?"],"pattern":"be + adjective","point":"be + adjective"}],"phrases":[{"audio_key":"a1_study_t06_l09_phrase_01","example":"My book is missing.","formality":"neutral","phrase":"My book is missing.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t06_l09_phrase_02","example":"This is difficult.","formality":"neutral","phrase":"This is difficult.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t06_l09_phrase_03","example":"Can you help me fix it?","formality":"neutral","phrase":"Can you help me fix it?","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t06_l09_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Stress key words in polite requests for help.","model":"My book is missing.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t06_l09_vocab_01","example":"I use the word ''missing'' in this lesson.","image_key":"a1_study_t06_l09_vocab_01","meaning":"A key word used in this lesson: missing.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''missing''.","word":"missing"},{"audio_key":"a1_study_t06_l09_vocab_02","example":"I use the word ''broken'' in this lesson.","image_key":"a1_study_t06_l09_vocab_02","meaning":"A key word used in this lesson: broken.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''broken''.","word":"broken"},{"audio_key":"a1_study_t06_l09_vocab_03","example":"I use the word ''wrong'' in this lesson.","image_key":"a1_study_t06_l09_vocab_03","meaning":"A key word used in this lesson: wrong.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''wrong''.","word":"wrong"},{"audio_key":"a1_study_t06_l09_vocab_04","example":"I use the word ''difficult'' in this lesson.","image_key":"a1_study_t06_l09_vocab_04","meaning":"A key word used in this lesson: difficult.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''difficult''.","word":"difficult"},{"audio_key":"a1_study_t06_l09_vocab_05","example":"I use the word ''problem'' in this lesson.","image_key":"a1_study_t06_l09_vocab_05","meaning":"A key word used in this lesson: problem.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''problem''.","word":"problem"}]},"title":"Solve the Problem"}'::jsonb, NOW(), NOW())
