INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('e45e5e50-acee-5b85-aaf3-e9d4f9c32043', NULL, 'Help Mission', 'Handle a difficult classroom moment in English.

The learner uses English in a realistic study situation focused on help mission.', 9, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"I need help with...","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["I need help with...","Could you explain it?","Now I understand."],"points":10,"prompt":"Which phrase best helps you: handle a difficult classroom moment in english.","type":"multiple_choice"},{"answer":["I need help with...","Could you explain it?","Now I understand."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["I need help with...","Could you explain it?","Now I understand."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Complete a full teacher-help roleplay.","type":"recording"}],"final_task":{"learner_instruction":"Complete a full teacher-help roleplay. Speak for at least 65 seconds.","minimum_seconds":65,"required_language":["I need help with...","Could you explain it?"],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Complete a full teacher-help roleplay.","task_type":"simulation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T06_L10","lesson_number":10,"mission":"Handle a difficult classroom moment in English.","objectives":["Use key words and phrases to handle a difficult classroom moment in english.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on help mission.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to handle a difficult classroom moment in english.","examples":["I need help with...","Could you explain it?","Now I understand."],"pattern":"integrated review","point":"integrated review"}],"phrases":[{"audio_key":"a1_study_t06_l10_phrase_01","example":"I need help with...","formality":"neutral","phrase":"I need help with...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t06_l10_phrase_02","example":"Could you explain it?","formality":"neutral","phrase":"Could you explain it?","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t06_l10_phrase_03","example":"Now I understand.","formality":"neutral","phrase":"Now I understand.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t06_l10_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Stress key words in polite requests for help.","model":"I need help with...","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t06_l10_vocab_01","example":"I use the word ''clarify'' in this lesson.","image_key":"a1_study_t06_l10_vocab_01","meaning":"A key word used in this lesson: clarify.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''clarify''.","word":"clarify"},{"audio_key":"a1_study_t06_l10_vocab_02","example":"I use the word ''repeat'' in this lesson.","image_key":"a1_study_t06_l10_vocab_02","meaning":"A key word used in this lesson: repeat.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''repeat''.","word":"repeat"},{"audio_key":"a1_study_t06_l10_vocab_03","example":"I use the word ''example'' in this lesson.","image_key":"a1_study_t06_l10_vocab_03","meaning":"A key word used in this lesson: example.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''example''.","word":"example"},{"audio_key":"a1_study_t06_l10_vocab_04","example":"I use the word ''check'' in this lesson.","image_key":"a1_study_t06_l10_vocab_04","meaning":"A key word used in this lesson: check.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''check''.","word":"check"},{"audio_key":"a1_study_t06_l10_vocab_05","example":"I use the word ''understand'' in this lesson.","image_key":"a1_study_t06_l10_vocab_05","meaning":"A key word used in this lesson: understand.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''understand''.","word":"understand"}]},"title":"Help Mission"}'::jsonb, NOW(), NOW())
