VALUES ('017ef18b-c786-5171-b875-b1c2d039953f', 'e45e5e50-acee-5b85-aaf3-e9d4f9c32043', 'activity', 'AI Speaking Mission', '{"activity_id":"ACT_09","activity_type":"ai_roleplay","ai_config":{"allowed_vocabulary":["i","need","help","with","could","you","explain","it","now","i","understand"],"correction_style":"hint_first","difficulty_adjustment":"adaptive_by_confidence","learner_level":"A1","max_turns":8,"opening_message":"I need help with...","persona":"Warm, patient, encouraging, and concise. Use only beginner-friendly English.","role":"classmate or teacher in the lesson scenario","scoring_rubric":[{"criterion":"task_completion","description":"The learner completes the communication mission.","weight":0.4},{"criterion":"intelligibility","description":"The learner is understandable.","weight":0.3},{"criterion":"target_language","description":"The learner uses lesson words and phrases.","weight":0.3}],"system_prompt":"You are an A1 English speaking partner. Help the learner complete this mission: Complete a full teacher-help roleplay. Use short sentences, one question at a time, and familiar vocabulary. Do not give long grammar explanations. Recast serious errors gently and praise successful communication.","target_phrases":["I need help with...","Could you explain it?","Now I understand."]},"content":{"required_phrases":["I need help with...","Could you explain it?"],"scenario":"Complete a full teacher-help roleplay.","success_message":"Mission complete! You communicated successfully."},"estimated_seconds":180,"instructions":"Complete the mission with the AI partner.","order":9,"retry_logic":{"fallback_activity":"Play a slower model, show a sentence frame, and let the learner try again.","hint_after_attempt":1,"max_attempts":3},"source_activity":{"activity_id":"ACT_09","ai_config":{"allowed_vocabulary":["i","need","help","with","could","you","explain","it","now","i","understand"],"correction_style":"hint_first","difficulty_adjustment":"adaptive_by_confidence","learner_level":"A1","max_turns":8,"opening_message":"I need help with...","persona":"Warm, patient, encouraging, and concise. Use only beginner-friendly English.","role":"classmate or teacher in the lesson scenario","scoring_rubric":[{"criterion":"task_completion","description":"The learner completes the communication mission.","weight":0.4},{"criterion":"intelligibility","description":"The learner is understandable.","weight":0.3},{"criterion":"target_language","description":"The learner uses lesson words and phrases.","weight":0.3}],"system_prompt":"You are an A1 English speaking partner. Help the learner complete this mission: Complete a full teacher-help roleplay. Use short sentences, one question at a time, and familiar vocabulary. Do not give long grammar explanations. Recast serious errors gently and praise successful communication.","target_phrases":["I need help with...","Could you explain it?","Now I understand."]},"content":{"required_phrases":["I need help with...","Could you explain it?"],"scenario":"Complete a full teacher-help roleplay.","success_message":"Mission complete! You communicated successfully."},"estimated_seconds":180,"instructions":"Complete the mission with the AI partner.","order":9,"retry_logic":{"fallback_activity":"Play a slower model, show a sentence frame, and let the learner try again.","hint_after_attempt":1,"max_attempts":3},"success_criteria":["The learner completes the mission.","The learner uses at least two target phrases."],"title":"AI Speaking Mission","type":"ai_roleplay"},"success_criteria":["The learner completes the mission.","The learner uses at least two target phrases."],"title":"AI Speaking Mission","type":"ai_roleplay"}'::jsonb, 8, NOW(), NOW())
