INSERT INTO courses.learning_tracks (id, code, title, description, language, level, track_type, motivation, is_published, sort_order, source_metadata, created_at, updated_at)
VALUES ('07833c42-aac2-5c1f-aac9-d701cb645c3c', 'A1_STUDY_T07', 'Studying Together', 'A collaborative A1 track for inviting classmates to study, suggesting activities, agreeing, disagreeing politely, and making a simple study plan.', 'en', 'A1', 'thematic', ARRAY['study']::text[], true, 7, '{"package":{"goal":"study","lesson_count":100,"level":"A1","package_id":"A1_STUDY_TRACKS_01_10","recommended_import_order":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"schema_version":"1.0.0","titles":["My First English Class","My Classroom","My School Life","Meeting Friends at School","My Study Day","Asking for Help","Studying Together","School Projects","Tests and Exams","Becoming an Independent Learner"],"track_count":10,"track_ids":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"validation":"All files passed the uploaded JSON Schema using Draft 2020-12."},"track":{"analytics":{"events":["track_started","lesson_started","lesson_completed","speaking_attempted","speaking_passed","mission_attempted","mission_completed","track_completed","track_abandoned"],"mastery_metrics":["pronunciation_accuracy","fluency_score","grammar_accuracy","vocabulary_recall","listening_comprehension","response_relevance","confidence_score","completion_rate"]},"communication_outcome":"The learner can arrange a basic study session and communicate simple choices and responsibilities.","completion_rules":{"maximum_attempts":null,"minimum_average_score":70,"minimum_lessons_completed":10,"required_final_mission":true,"speaking_pass_score":65},"description":"A collaborative A1 track for inviting classmates to study, suggesting activities, agreeing, disagreeing politely, and making a simple study plan.","difficulty":{"cefr":"A1","speaking_target_seconds":180,"stage":"beginner","target_words_per_minute":57},"estimated_duration_minutes":120,"goal":"study","language_systems":{"discourse":["short question-answer exchanges","basic turn taking","simple repair strategies","sequencing short ideas"],"functions":["inviting","suggesting","agreeing","disagreeing","planning"],"grammar":["Let''s","Can for ability and requests","Want to","Basic conjunctions"],"pronunciation":[{"description":"Friendly intonation for suggestions, agreement, and polite disagreement.","focus":"intonation","language_interference_notes":["Use clear English word order.","Do not drop important final consonants.","Avoid adding extra vowel sounds between consonants."]}],"vocabulary":{"core_phrases":["Let''s study together.","Do you want to study?","Can we meet tomorrow?","Are you free at five?","Yes, I am.","Sorry, I am busy.","Let''s meet at the library.","Is the cafe quiet?","We can study online.","Let''s practice speaking.","We need to do homework.","I want to study vocabulary.","I can read the text.","Can you explain this?","We can help each other.","Good idea.","That sounds great.","Yes, let''s do that.","Maybe, but...","Let''s do this instead."],"target_word_count":50,"themes":["study plans","group work","suggestions","agreement"]}},"learner_identity":"I can study and make plans with classmates.","learning_objectives":[{"can_do_statement":"I can study and make plans with classmates.","measurable_success":"Completes the final speaking mission for Studying Together.","objective_id":"OBJ_01","skill":"speaking"},{"can_do_statement":"I can understand short, clear English in this study situation.","measurable_success":"Answers at least 70 percent of listening checks correctly.","objective_id":"OBJ_02","skill":"listening"},{"can_do_statement":"I can use useful words and phrases in a short conversation.","measurable_success":"Uses target language in a multi-turn AI roleplay.","objective_id":"OBJ_03","skill":"interaction"},{"can_do_statement":"I can speak clearly enough for a patient listener to understand me.","measurable_success":"Achieves at least 65 on the speaking rubric.","objective_id":"OBJ_04","skill":"pronunciation"}],"level":"A1","prerequisites":["A1_STUDY_T06"],"progression":{"entry_ability":"The learner has completed the previous A1 Study track or demonstrates equivalent beginner ability.","exit_ability":"The learner can arrange a basic study session and communicate simple choices and responsibilities.","next_track_unlocks":"A1_STUDY_T08","spiral_review":["Let''s","Can for ability and requests","Want to","Basic conjunctions","study plans","group work","suggestions"]},"rewards":{"badge":{"badge_id":"BADGE_A1_STUDY_T07","description":"Completed the A1 Study track: Studying Together.","icon_key":"badge_a1_study_t07","name":"Studying Together"},"certificate_eligible":false,"unlock_message":"You completed Studying Together and can now use English in this study situation.","xp":1000},"schema_version":"1.0.0","short_title":"Studying Together","title":"Studying Together","track_id":"A1_STUDY_T07","track_number":7}}'::jsonb, NOW(), NOW())
