INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('836e7e6a-d148-532d-9419-6d9a27d2c9c4', NULL, 'Choose a Time', 'Agree on a simple meeting time.

The learner uses English in a realistic study situation focused on choose a time.', 1, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Are you free at five?","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Are you free at five?","Yes, I am.","Sorry, I am busy."],"points":10,"prompt":"Which phrase best helps you: agree on a simple meeting time.","type":"multiple_choice"},{"answer":["Are you free at five?","Yes, I am.","Sorry, I am busy."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Are you free at five?","Yes, I am.","Sorry, I am busy."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Choose a time that works.","type":"recording"}],"final_task":{"learner_instruction":"Choose a time that works. Speak for at least 25 seconds.","minimum_seconds":25,"required_language":["Are you free at five?","Yes, I am."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Choose a time that works.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T07_L02","lesson_number":2,"mission":"Agree on a simple meeting time.","objectives":["Use key words and phrases to agree on a simple meeting time.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on choose a time.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to agree on a simple meeting time.","examples":["Are you free at five?","Yes, I am.","Sorry, I am busy."],"pattern":"be + free/busy","point":"be + free/busy"}],"phrases":[{"audio_key":"a1_study_t07_l02_phrase_01","example":"Are you free at five?","formality":"neutral","phrase":"Are you free at five?","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t07_l02_phrase_02","example":"Yes, I am.","formality":"neutral","phrase":"Yes, I am.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t07_l02_phrase_03","example":"Sorry, I am busy.","formality":"neutral","phrase":"Sorry, I am busy.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t07_l02_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Friendly intonation for suggestions, agreement, and polite disagreement.","model":"Are you free at five?","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t07_l02_vocab_01","example":"I use the word ''morning'' in this lesson.","image_key":"a1_study_t07_l02_vocab_01","meaning":"A key word used in this lesson: morning.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''morning''.","word":"morning"},{"audio_key":"a1_study_t07_l02_vocab_02","example":"I use the word ''afternoon'' in this lesson.","image_key":"a1_study_t07_l02_vocab_02","meaning":"A key word used in this lesson: afternoon.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''afternoon''.","word":"afternoon"},{"audio_key":"a1_study_t07_l02_vocab_03","example":"I use the word ''evening'' in this lesson.","image_key":"a1_study_t07_l02_vocab_03","meaning":"A key word used in this lesson: evening.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''evening''.","word":"evening"},{"audio_key":"a1_study_t07_l02_vocab_04","example":"I use the word ''free'' in this lesson.","image_key":"a1_study_t07_l02_vocab_04","meaning":"A key word used in this lesson: free.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''free''.","word":"free"},{"audio_key":"a1_study_t07_l02_vocab_05","example":"I use the word ''busy'' in this lesson.","image_key":"a1_study_t07_l02_vocab_05","meaning":"A key word used in this lesson: busy.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''busy''.","word":"busy"}]},"title":"Choose a Time"}'::jsonb, NOW(), NOW())
