INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('a008b150-8237-58f3-b744-f76d16aede3b', NULL, 'Choose a Place', 'Agree on where to study.

The learner uses English in a realistic study situation focused on choose a place.', 2, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Let''s meet at the library.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Let''s meet at the library.","Is the cafe quiet?","We can study online."],"points":10,"prompt":"Which phrase best helps you: agree on where to study.","type":"multiple_choice"},{"answer":["Let''s meet at the library.","Is the cafe quiet?","We can study online."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Let''s meet at the library.","Is the cafe quiet?","We can study online."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Choose a study location.","type":"recording"}],"final_task":{"learner_instruction":"Choose a study location. Speak for at least 30 seconds.","minimum_seconds":30,"required_language":["Let''s meet at the library.","Is the cafe quiet?"],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Choose a study location.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T07_L03","lesson_number":3,"mission":"Agree on where to study.","objectives":["Use key words and phrases to agree on where to study.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on choose a place.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to agree on where to study.","examples":["Let''s meet at the library.","Is the cafe quiet?","We can study online."],"pattern":"at + place; can","point":"at + place; can"}],"phrases":[{"audio_key":"a1_study_t07_l03_phrase_01","example":"Let''s meet at the library.","formality":"neutral","phrase":"Let''s meet at the library.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t07_l03_phrase_02","example":"Is the cafe quiet?","formality":"neutral","phrase":"Is the cafe quiet?","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t07_l03_phrase_03","example":"We can study online.","formality":"neutral","phrase":"We can study online.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t07_l03_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Friendly intonation for suggestions, agreement, and polite disagreement.","model":"Let''s meet at the library.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t07_l03_vocab_01","example":"I use the word ''library'' in this lesson.","image_key":"a1_study_t07_l03_vocab_01","meaning":"A key word used in this lesson: library.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''library''.","word":"library"},{"audio_key":"a1_study_t07_l03_vocab_02","example":"I use the word ''cafe'' in this lesson.","image_key":"a1_study_t07_l03_vocab_02","meaning":"A key word used in this lesson: cafe.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''cafe''.","word":"cafe"},{"audio_key":"a1_study_t07_l03_vocab_03","example":"I use the word ''home'' in this lesson.","image_key":"a1_study_t07_l03_vocab_03","meaning":"A key word used in this lesson: home.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''home''.","word":"home"},{"audio_key":"a1_study_t07_l03_vocab_04","example":"I use the word ''online'' in this lesson.","image_key":"a1_study_t07_l03_vocab_04","meaning":"A key word used in this lesson: online.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''online''.","word":"online"},{"audio_key":"a1_study_t07_l03_vocab_05","example":"I use the word ''quiet'' in this lesson.","image_key":"a1_study_t07_l03_vocab_05","meaning":"A key word used in this lesson: quiet.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''quiet''.","word":"quiet"}]},"title":"Choose a Place"}'::jsonb, NOW(), NOW())
