INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('91d6a9c3-bc31-52e3-9d51-0eb3c4d8b136', NULL, 'Divide the Work', 'Give simple tasks to group members.

The learner uses English in a realistic study situation focused on divide the work.', 7, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"You read part one.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["You read part one.","I can write.","She can find the answers."],"points":10,"prompt":"Which phrase best helps you: give simple tasks to group members.","type":"multiple_choice"},{"answer":["You read part one.","I can write.","She can find the answers."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["You read part one.","I can write.","She can find the answers."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Divide four tasks fairly.","type":"recording"}],"final_task":{"learner_instruction":"Divide four tasks fairly. Speak for at least 55 seconds.","minimum_seconds":55,"required_language":["You read part one.","I can write."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Divide four tasks fairly.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T07_L08","lesson_number":8,"mission":"Give simple tasks to group members.","objectives":["Use key words and phrases to give simple tasks to group members.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on divide the work.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to give simple tasks to group members.","examples":["You read part one.","I can write.","She can find the answers."],"pattern":"subject + can","point":"subject + can"}],"phrases":[{"audio_key":"a1_study_t07_l08_phrase_01","example":"You read part one.","formality":"neutral","phrase":"You read part one.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t07_l08_phrase_02","example":"I can write.","formality":"neutral","phrase":"I can write.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t07_l08_phrase_03","example":"She can find the answers.","formality":"neutral","phrase":"She can find the answers.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t07_l08_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Friendly intonation for suggestions, agreement, and polite disagreement.","model":"You read part one.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t07_l08_vocab_01","example":"I use the word ''read'' in this lesson.","image_key":"a1_study_t07_l08_vocab_01","meaning":"A key word used in this lesson: read.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''read''.","word":"read"},{"audio_key":"a1_study_t07_l08_vocab_02","example":"I use the word ''write'' in this lesson.","image_key":"a1_study_t07_l08_vocab_02","meaning":"A key word used in this lesson: write.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''write''.","word":"write"},{"audio_key":"a1_study_t07_l08_vocab_03","example":"I use the word ''find'' in this lesson.","image_key":"a1_study_t07_l08_vocab_03","meaning":"A key word used in this lesson: find.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''find''.","word":"find"},{"audio_key":"a1_study_t07_l08_vocab_04","example":"I use the word ''present'' in this lesson.","image_key":"a1_study_t07_l08_vocab_04","meaning":"A key word used in this lesson: present.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''present''.","word":"present"},{"audio_key":"a1_study_t07_l08_vocab_05","example":"I use the word ''part'' in this lesson.","image_key":"a1_study_t07_l08_vocab_05","meaning":"A key word used in this lesson: part.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''part''.","word":"part"}]},"title":"Divide the Work"}'::jsonb, NOW(), NOW())
