INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('55b6f5f6-d8a7-56df-b297-07e7bfc28344', NULL, 'Study Session Mission', 'Plan and begin a realistic group study session.

The learner uses English in a realistic study situation focused on study session mission.', 9, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Let''s start.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Let''s start.","What should we do first?","I can help with that."],"points":10,"prompt":"Which phrase best helps you: plan and begin a realistic group study session.","type":"multiple_choice"},{"answer":["Let''s start.","What should we do first?","I can help with that."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Let''s start.","What should we do first?","I can help with that."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Complete a two-minute planning conversation.","type":"recording"}],"final_task":{"learner_instruction":"Complete a two-minute planning conversation. Speak for at least 65 seconds.","minimum_seconds":65,"required_language":["Let''s start.","What should we do first?"],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Complete a two-minute planning conversation.","task_type":"simulation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T07_L10","lesson_number":10,"mission":"Plan and begin a realistic group study session.","objectives":["Use key words and phrases to plan and begin a realistic group study session.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on study session mission.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to plan and begin a realistic group study session.","examples":["Let''s start.","What should we do first?","I can help with that."],"pattern":"integrated review","point":"integrated review"}],"phrases":[{"audio_key":"a1_study_t07_l10_phrase_01","example":"Let''s start.","formality":"neutral","phrase":"Let''s start.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t07_l10_phrase_02","example":"What should we do first?","formality":"neutral","phrase":"What should we do first?","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t07_l10_phrase_03","example":"I can help with that.","formality":"neutral","phrase":"I can help with that.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t07_l10_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Friendly intonation for suggestions, agreement, and polite disagreement.","model":"Let''s start.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t07_l10_vocab_01","example":"I use the word ''invite'' in this lesson.","image_key":"a1_study_t07_l10_vocab_01","meaning":"A key word used in this lesson: invite.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''invite''.","word":"invite"},{"audio_key":"a1_study_t07_l10_vocab_02","example":"I use the word ''choose'' in this lesson.","image_key":"a1_study_t07_l10_vocab_02","meaning":"A key word used in this lesson: choose.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''choose''.","word":"choose"},{"audio_key":"a1_study_t07_l10_vocab_03","example":"I use the word ''agree'' in this lesson.","image_key":"a1_study_t07_l10_vocab_03","meaning":"A key word used in this lesson: agree.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''agree''.","word":"agree"},{"audio_key":"a1_study_t07_l10_vocab_04","example":"I use the word ''task'' in this lesson.","image_key":"a1_study_t07_l10_vocab_04","meaning":"A key word used in this lesson: task.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''task''.","word":"task"},{"audio_key":"a1_study_t07_l10_vocab_05","example":"I use the word ''plan'' in this lesson.","image_key":"a1_study_t07_l10_vocab_05","meaning":"A key word used in this lesson: plan.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''plan''.","word":"plan"}]},"title":"Study Session Mission"}'::jsonb, NOW(), NOW())
