VALUES ('7d279d99-7290-5e0e-8a87-598bae7bcd76', 'A1_STUDY_T08', 'School Projects', 'A project-based A1 track for discussing a simple assignment, dividing tasks, giving basic opinions, reporting progress, and presenting short results.', 'en', 'A1', 'thematic', ARRAY['study']::text[], true, 8, '{"package":{"goal":"study","lesson_count":100,"level":"A1","package_id":"A1_STUDY_TRACKS_01_10","recommended_import_order":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"schema_version":"1.0.0","titles":["My First English Class","My Classroom","My School Life","Meeting Friends at School","My Study Day","Asking for Help","Studying Together","School Projects","Tests and Exams","Becoming an Independent Learner"],"track_count":10,"track_ids":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"validation":"All files passed the uploaded JSON Schema using Draft 2020-12."},"track":{"analytics":{"events":["track_started","lesson_started","lesson_completed","speaking_attempted","speaking_passed","mission_attempted","mission_completed","track_completed","track_abandoned"],"mastery_metrics":["pronunciation_accuracy","fluency_score","grammar_accuracy","vocabulary_recall","listening_comprehension","response_relevance","confidence_score","completion_rate"]},"communication_outcome":"The learner can participate in a simple group project and explain their task and progress.","completion_rules":{"maximum_attempts":null,"minimum_average_score":70,"minimum_lessons_completed":10,"required_final_mission":true,"speaking_pass_score":65},"description":"A project-based A1 track for discussing a simple assignment, dividing tasks, giving basic opinions, reporting progress, and presenting short results.","difficulty":{"cefr":"A1","speaking_target_seconds":200,"stage":"beginner","target_words_per_minute":59},"estimated_duration_minutes":120,"goal":"study","language_systems":{"discourse":["short question-answer exchanges","basic turn taking","simple repair strategies","sequencing short ideas"],"functions":["describing a project","assigning tasks","reporting progress","giving opinions"],"grammar":["Have to","Can","Present continuous","Basic opinion phrases"],"pronunciation":[{"description":"Pause clearly between short ideas in project updates.","focus":"thought_groups","language_interference_notes":["Use clear English word order.","Do not drop important final consonants.","Avoid adding extra vowel sounds between consonants."]}],"vocabulary":{"core_phrases":["Our project is about...","The goal is to...","We are a team of four.","We need paper.","Do we need pictures?","We need a computer.","I can write.","You can draw.","Who can present?","We have to finish today.","I have to bring pictures.","Do we have to present?","I think this is good.","This picture is better.","The title is clear.","I am writing the title.","She is drawing.","We are checking the facts.","The picture is missing.","The text is too small."],"target_word_count":50,"themes":["projects","tasks","materials","progress","presentation"]}},"learner_identity":"I can work with a group on a simple school project.","learning_objectives":[{"can_do_statement":"I can work with a group on a simple school project.","measurable_success":"Completes the final speaking mission for School Projects.","objective_id":"OBJ_01","skill":"speaking"},{"can_do_statement":"I can understand short, clear English in this study situation.","measurable_success":"Answers at least 70 percent of listening checks correctly.","objective_id":"OBJ_02","skill":"listening"},{"can_do_statement":"I can use useful words and phrases in a short conversation.","measurable_success":"Uses target language in a multi-turn AI roleplay.","objective_id":"OBJ_03","skill":"interaction"},{"can_do_statement":"I can speak clearly enough for a patient listener to understand me.","measurable_success":"Achieves at least 65 on the speaking rubric.","objective_id":"OBJ_04","skill":"pronunciation"}],"level":"A1","prerequisites":["A1_STUDY_T07"],"progression":{"entry_ability":"The learner has completed the previous A1 Study track or demonstrates equivalent beginner ability.","exit_ability":"The learner can participate in a simple group project and explain their task and progress.","next_track_unlocks":"A1_STUDY_T09","spiral_review":["Have to","Can","Present continuous","Basic opinion phrases","projects","tasks","materials"]},"rewards":{"badge":{"badge_id":"BADGE_A1_STUDY_T08","description":"Completed the A1 Study track: School Projects.","icon_key":"badge_a1_study_t08","name":"School Projects"},"certificate_eligible":false,"unlock_message":"You completed School Projects and can now use English in this study situation.","xp":1000},"schema_version":"1.0.0","short_title":"School Projects","title":"School Projects","track_id":"A1_STUDY_T08","track_number":8}}'::jsonb, NOW(), NOW())
