INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('b92edd9a-74a7-5884-89f0-dc1c993a9dd9', NULL, 'Our Project', 'Describe the topic and goal of a project.

The learner uses English in a realistic study situation focused on our project.', 0, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Our project is about...","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Our project is about...","The goal is to...","We are a team of four."],"points":10,"prompt":"Which phrase best helps you: describe the topic and goal of a project.","type":"multiple_choice"},{"answer":["Our project is about...","The goal is to...","We are a team of four."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Our project is about...","The goal is to...","We are a team of four."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Explain the project in three sentences.","type":"recording"}],"final_task":{"learner_instruction":"Explain the project in three sentences. Speak for at least 20 seconds.","minimum_seconds":20,"required_language":["Our project is about...","The goal is to..."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Explain the project in three sentences.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T08_L01","lesson_number":1,"mission":"Describe the topic and goal of a project.","objectives":["Use key words and phrases to describe the topic and goal of a project.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on our project.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to describe the topic and goal of a project.","examples":["Our project is about...","The goal is to...","We are a team of four."],"pattern":"be about; goal is to","point":"be about; goal is to"}],"phrases":[{"audio_key":"a1_study_t08_l01_phrase_01","example":"Our project is about...","formality":"neutral","phrase":"Our project is about...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t08_l01_phrase_02","example":"The goal is to...","formality":"neutral","phrase":"The goal is to...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t08_l01_phrase_03","example":"We are a team of four.","formality":"neutral","phrase":"We are a team of four.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t08_l01_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Pause clearly between short ideas in project updates.","model":"Our project is about...","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t08_l01_vocab_01","example":"I use the word ''project'' in this lesson.","image_key":"a1_study_t08_l01_vocab_01","meaning":"A key word used in this lesson: project.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''project''.","word":"project"},{"audio_key":"a1_study_t08_l01_vocab_02","example":"I use the word ''topic'' in this lesson.","image_key":"a1_study_t08_l01_vocab_02","meaning":"A key word used in this lesson: topic.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''topic''.","word":"topic"},{"audio_key":"a1_study_t08_l01_vocab_03","example":"I use the word ''goal'' in this lesson.","image_key":"a1_study_t08_l01_vocab_03","meaning":"A key word used in this lesson: goal.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''goal''.","word":"goal"},{"audio_key":"a1_study_t08_l01_vocab_04","example":"I use the word ''team'' in this lesson.","image_key":"a1_study_t08_l01_vocab_04","meaning":"A key word used in this lesson: team.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''team''.","word":"team"},{"audio_key":"a1_study_t08_l01_vocab_05","example":"I use the word ''result'' in this lesson.","image_key":"a1_study_t08_l01_vocab_05","meaning":"A key word used in this lesson: result.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''result''.","word":"result"}]},"title":"Our Project"}'::jsonb, NOW(), NOW())
