INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('0c94d0b4-6e58-53d3-af1e-c4df84c1a875', NULL, 'Progress Update', 'Give a short update on completed and remaining work.

The learner uses English in a realistic study situation focused on progress update.', 7, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"My part is done.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["My part is done.","The poster is almost ready.","Next, we practice."],"points":10,"prompt":"Which phrase best helps you: give a short update on completed and remaining work.","type":"multiple_choice"},{"answer":["My part is done.","The poster is almost ready.","Next, we practice."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["My part is done.","The poster is almost ready.","Next, we practice."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Give a 30-second progress report.","type":"recording"}],"final_task":{"learner_instruction":"Give a 30-second progress report. Speak for at least 55 seconds.","minimum_seconds":55,"required_language":["My part is done.","The poster is almost ready."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Give a 30-second progress report.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T08_L08","lesson_number":8,"mission":"Give a short update on completed and remaining work.","objectives":["Use key words and phrases to give a short update on completed and remaining work.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on progress update.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to give a short update on completed and remaining work.","examples":["My part is done.","The poster is almost ready.","Next, we practice."],"pattern":"be + status words","point":"be + status words"}],"phrases":[{"audio_key":"a1_study_t08_l08_phrase_01","example":"My part is done.","formality":"neutral","phrase":"My part is done.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t08_l08_phrase_02","example":"The poster is almost ready.","formality":"neutral","phrase":"The poster is almost ready.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t08_l08_phrase_03","example":"Next, we practice.","formality":"neutral","phrase":"Next, we practice.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t08_l08_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Pause clearly between short ideas in project updates.","model":"My part is done.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t08_l08_vocab_01","example":"I use the word ''done'' in this lesson.","image_key":"a1_study_t08_l08_vocab_01","meaning":"A key word used in this lesson: done.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''done''.","word":"done"},{"audio_key":"a1_study_t08_l08_vocab_02","example":"I use the word ''ready'' in this lesson.","image_key":"a1_study_t08_l08_vocab_02","meaning":"A key word used in this lesson: ready.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''ready''.","word":"ready"},{"audio_key":"a1_study_t08_l08_vocab_03","example":"I use the word ''almost'' in this lesson.","image_key":"a1_study_t08_l08_vocab_03","meaning":"A key word used in this lesson: almost.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''almost''.","word":"almost"},{"audio_key":"a1_study_t08_l08_vocab_04","example":"I use the word ''still'' in this lesson.","image_key":"a1_study_t08_l08_vocab_04","meaning":"A key word used in this lesson: still.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''still''.","word":"still"},{"audio_key":"a1_study_t08_l08_vocab_05","example":"I use the word ''next'' in this lesson.","image_key":"a1_study_t08_l08_vocab_05","meaning":"A key word used in this lesson: next.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''next''.","word":"next"}]},"title":"Progress Update"}'::jsonb, NOW(), NOW())
