INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('62328c65-aef3-5aff-bce9-61b5dd41d52a', NULL, 'Practice the Presentation', 'Rehearse a short group presentation.

The learner uses English in a realistic study situation focused on practice the presentation.', 8, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Welcome to our presentation.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Welcome to our presentation.","First, I will explain...","Thank you for listening."],"points":10,"prompt":"Which phrase best helps you: rehearse a short group presentation.","type":"multiple_choice"},{"answer":["Welcome to our presentation.","First, I will explain...","Thank you for listening."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Welcome to our presentation.","First, I will explain...","Thank you for listening."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Deliver a short project section.","type":"recording"}],"final_task":{"learner_instruction":"Deliver a short project section. Speak for at least 60 seconds.","minimum_seconds":60,"required_language":["Welcome to our presentation.","First, I will explain..."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Deliver a short project section.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T08_L09","lesson_number":9,"mission":"Rehearse a short group presentation.","objectives":["Use key words and phrases to rehearse a short group presentation.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on practice the presentation.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to rehearse a short group presentation.","examples":["Welcome to our presentation.","First, I will explain...","Thank you for listening."],"pattern":"sequencing","point":"sequencing"}],"phrases":[{"audio_key":"a1_study_t08_l09_phrase_01","example":"Welcome to our presentation.","formality":"neutral","phrase":"Welcome to our presentation.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t08_l09_phrase_02","example":"First, I will explain...","formality":"neutral","phrase":"First, I will explain...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t08_l09_phrase_03","example":"Thank you for listening.","formality":"neutral","phrase":"Thank you for listening.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t08_l09_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Pause clearly between short ideas in project updates.","model":"Welcome to our presentation.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t08_l09_vocab_01","example":"I use the word ''welcome'' in this lesson.","image_key":"a1_study_t08_l09_vocab_01","meaning":"A key word used in this lesson: welcome.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''welcome''.","word":"welcome"},{"audio_key":"a1_study_t08_l09_vocab_02","example":"I use the word ''first'' in this lesson.","image_key":"a1_study_t08_l09_vocab_02","meaning":"A key word used in this lesson: first.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''first''.","word":"first"},{"audio_key":"a1_study_t08_l09_vocab_03","example":"I use the word ''next'' in this lesson.","image_key":"a1_study_t08_l09_vocab_03","meaning":"A key word used in this lesson: next.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''next''.","word":"next"},{"audio_key":"a1_study_t08_l09_vocab_04","example":"I use the word ''finally'' in this lesson.","image_key":"a1_study_t08_l09_vocab_04","meaning":"A key word used in this lesson: finally.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''finally''.","word":"finally"},{"audio_key":"a1_study_t08_l09_vocab_05","example":"I use the word ''thank'' in this lesson.","image_key":"a1_study_t08_l09_vocab_05","meaning":"A key word used in this lesson: thank.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''thank''.","word":"thank"}]},"title":"Practice the Presentation"}'::jsonb, NOW(), NOW())
