INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('5be00270-7be1-559c-ad79-23f900a9645f', NULL, 'Project Mission', 'Complete a group-project meeting and mini-presentation.

The learner uses English in a realistic study situation focused on project mission.', 9, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Our topic is...","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Our topic is...","My task is...","We are ready to present."],"points":10,"prompt":"Which phrase best helps you: complete a group-project meeting and mini-presentation.","type":"multiple_choice"},{"answer":["Our topic is...","My task is...","We are ready to present."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Our topic is...","My task is...","We are ready to present."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Complete a project meeting and one-minute presentation.","type":"recording"}],"final_task":{"learner_instruction":"Complete a project meeting and one-minute presentation. Speak for at least 65 seconds.","minimum_seconds":65,"required_language":["Our topic is...","My task is..."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Complete a project meeting and one-minute presentation.","task_type":"simulation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T08_L10","lesson_number":10,"mission":"Complete a group-project meeting and mini-presentation.","objectives":["Use key words and phrases to complete a group-project meeting and mini-presentation.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on project mission.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to complete a group-project meeting and mini-presentation.","examples":["Our topic is...","My task is...","We are ready to present."],"pattern":"integrated review","point":"integrated review"}],"phrases":[{"audio_key":"a1_study_t08_l10_phrase_01","example":"Our topic is...","formality":"neutral","phrase":"Our topic is...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t08_l10_phrase_02","example":"My task is...","formality":"neutral","phrase":"My task is...","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t08_l10_phrase_03","example":"We are ready to present.","formality":"neutral","phrase":"We are ready to present.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t08_l10_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Pause clearly between short ideas in project updates.","model":"Our topic is...","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t08_l10_vocab_01","example":"I use the word ''topic'' in this lesson.","image_key":"a1_study_t08_l10_vocab_01","meaning":"A key word used in this lesson: topic.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''topic''.","word":"topic"},{"audio_key":"a1_study_t08_l10_vocab_02","example":"I use the word ''task'' in this lesson.","image_key":"a1_study_t08_l10_vocab_02","meaning":"A key word used in this lesson: task.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''task''.","word":"task"},{"audio_key":"a1_study_t08_l10_vocab_03","example":"I use the word ''progress'' in this lesson.","image_key":"a1_study_t08_l10_vocab_03","meaning":"A key word used in this lesson: progress.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''progress''.","word":"progress"},{"audio_key":"a1_study_t08_l10_vocab_04","example":"I use the word ''problem'' in this lesson.","image_key":"a1_study_t08_l10_vocab_04","meaning":"A key word used in this lesson: problem.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''problem''.","word":"problem"},{"audio_key":"a1_study_t08_l10_vocab_05","example":"I use the word ''present'' in this lesson.","image_key":"a1_study_t08_l10_vocab_05","meaning":"A key word used in this lesson: present.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''present''.","word":"present"}]},"title":"Project Mission"}'::jsonb, NOW(), NOW())
