VALUES ('e947ee83-18b6-51b8-82e1-e4c304996c52', 'A1_STUDY_T09', 'Tests and Exams', 'An A1 academic-survival track for understanding test instructions, asking permitted questions, discussing preparation, and talking simply about results.', 'en', 'A1', 'thematic', ARRAY['study']::text[], true, 9, '{"package":{"goal":"study","lesson_count":100,"level":"A1","package_id":"A1_STUDY_TRACKS_01_10","recommended_import_order":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"schema_version":"1.0.0","titles":["My First English Class","My Classroom","My School Life","Meeting Friends at School","My Study Day","Asking for Help","Studying Together","School Projects","Tests and Exams","Becoming an Independent Learner"],"track_count":10,"track_ids":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"validation":"All files passed the uploaded JSON Schema using Draft 2020-12."},"track":{"analytics":{"events":["track_started","lesson_started","lesson_completed","speaking_attempted","speaking_passed","mission_attempted","mission_completed","track_completed","track_abandoned"],"mastery_metrics":["pronunciation_accuracy","fluency_score","grammar_accuracy","vocabulary_recall","listening_comprehension","response_relevance","confidence_score","completion_rate"]},"communication_outcome":"The learner can follow basic exam instructions, clarify simple rules, and describe preparation and results.","completion_rules":{"maximum_attempts":null,"minimum_average_score":70,"minimum_lessons_completed":10,"required_final_mission":true,"speaking_pass_score":65},"description":"An A1 academic-survival track for understanding test instructions, asking permitted questions, discussing preparation, and talking simply about results.","difficulty":{"cefr":"A1","speaking_target_seconds":220,"stage":"beginner","target_words_per_minute":61},"estimated_duration_minutes":120,"goal":"study","language_systems":{"discourse":["short question-answer exchanges","basic turn taking","simple repair strategies","sequencing short ideas"],"functions":["understanding rules","asking exam questions","describing preparation","discussing results"],"grammar":["Must and must not","Can and cannot","Past of be","Basic quantity words"],"pronunciation":[{"description":"Stress important instruction and rule words.","focus":"sentence_stress","language_interference_notes":["Use clear English word order.","Do not drop important final consonants.","Avoid adding extra vowel sounds between consonants."]}],"vocabulary":{"core_phrases":["I studied last night.","I am ready.","I am a little nervous.","Bring a pencil.","Do we need ID?","Can I use a dictionary?","Choose one answer.","Circle the correct word.","Complete the sentence.","What does this instruction mean?","Can you explain the example?","Which part?","You must be quiet.","You must not use your phone.","You must finish on time.","How much time is left?","Ten minutes are left.","The test finishes at eleven.","My pencil is broken.","I cannot see the clock."],"target_word_count":50,"themes":["exam instructions","preparation","rules","results","feelings"]}},"learner_identity":"I can communicate before, during, and after a simple test.","learning_objectives":[{"can_do_statement":"I can communicate before, during, and after a simple test.","measurable_success":"Completes the final speaking mission for Tests and Exams.","objective_id":"OBJ_01","skill":"speaking"},{"can_do_statement":"I can understand short, clear English in this study situation.","measurable_success":"Answers at least 70 percent of listening checks correctly.","objective_id":"OBJ_02","skill":"listening"},{"can_do_statement":"I can use useful words and phrases in a short conversation.","measurable_success":"Uses target language in a multi-turn AI roleplay.","objective_id":"OBJ_03","skill":"interaction"},{"can_do_statement":"I can speak clearly enough for a patient listener to understand me.","measurable_success":"Achieves at least 65 on the speaking rubric.","objective_id":"OBJ_04","skill":"pronunciation"}],"level":"A1","prerequisites":["A1_STUDY_T08"],"progression":{"entry_ability":"The learner has completed the previous A1 Study track or demonstrates equivalent beginner ability.","exit_ability":"The learner can follow basic exam instructions, clarify simple rules, and describe preparation and results.","next_track_unlocks":"A1_STUDY_T10","spiral_review":["Must and must not","Can and cannot","Past of be","Basic quantity words","exam instructions","preparation","rules"]},"rewards":{"badge":{"badge_id":"BADGE_A1_STUDY_T09","description":"Completed the A1 Study track: Tests and Exams.","icon_key":"badge_a1_study_t09","name":"Tests and Exams"},"certificate_eligible":false,"unlock_message":"You completed Tests and Exams and can now use English in this study situation.","xp":1000},"schema_version":"1.0.0","short_title":"Tests and Exams","title":"Tests and Exams","track_id":"A1_STUDY_T09","track_number":9}}'::jsonb, NOW(), NOW())
