INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('7ebc1cc8-754f-5c18-b0ae-ab116c219d5c', NULL, 'Before the Test', 'Talk about basic test preparation.

The learner uses English in a realistic study situation focused on before the test.', 0, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"I studied last night.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["I studied last night.","I am ready.","I am a little nervous."],"points":10,"prompt":"Which phrase best helps you: talk about basic test preparation.","type":"multiple_choice"},{"answer":["I studied last night.","I am ready.","I am a little nervous."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["I studied last night.","I am ready.","I am a little nervous."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Describe how you prepared.","type":"recording"}],"final_task":{"learner_instruction":"Describe how you prepared. Speak for at least 20 seconds.","minimum_seconds":20,"required_language":["I studied last night.","I am ready."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Describe how you prepared.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T09_L01","lesson_number":1,"mission":"Talk about basic test preparation.","objectives":["Use key words and phrases to talk about basic test preparation.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on before the test.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to talk about basic test preparation.","examples":["I studied last night.","I am ready.","I am a little nervous."],"pattern":"past of be; simple past chunks","point":"past of be; simple past chunks"}],"phrases":[{"audio_key":"a1_study_t09_l01_phrase_01","example":"I studied last night.","formality":"neutral","phrase":"I studied last night.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t09_l01_phrase_02","example":"I am ready.","formality":"neutral","phrase":"I am ready.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t09_l01_phrase_03","example":"I am a little nervous.","formality":"neutral","phrase":"I am a little nervous.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t09_l01_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Stress important instruction and rule words.","model":"I studied last night.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t09_l01_vocab_01","example":"I use the word ''study'' in this lesson.","image_key":"a1_study_t09_l01_vocab_01","meaning":"A key word used in this lesson: study.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''study''.","word":"study"},{"audio_key":"a1_study_t09_l01_vocab_02","example":"I use the word ''review'' in this lesson.","image_key":"a1_study_t09_l01_vocab_02","meaning":"A key word used in this lesson: review.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''review''.","word":"review"},{"audio_key":"a1_study_t09_l01_vocab_03","example":"I use the word ''practice'' in this lesson.","image_key":"a1_study_t09_l01_vocab_03","meaning":"A key word used in this lesson: practice.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''practice''.","word":"practice"},{"audio_key":"a1_study_t09_l01_vocab_04","example":"I use the word ''ready'' in this lesson.","image_key":"a1_study_t09_l01_vocab_04","meaning":"A key word used in this lesson: ready.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''ready''.","word":"ready"},{"audio_key":"a1_study_t09_l01_vocab_05","example":"I use the word ''nervous'' in this lesson.","image_key":"a1_study_t09_l01_vocab_05","meaning":"A key word used in this lesson: nervous.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''nervous''.","word":"nervous"}]},"title":"Before the Test"}'::jsonb, NOW(), NOW())
