INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('fdeb7f3f-da9c-5950-a23f-d27ad051f279', NULL, 'Test Materials', 'Identify what learners need for a test.

The learner uses English in a realistic study situation focused on test materials.', 1, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"Bring a pencil.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["Bring a pencil.","Do we need ID?","Can I use a dictionary?"],"points":10,"prompt":"Which phrase best helps you: identify what learners need for a test.","type":"multiple_choice"},{"answer":["Bring a pencil.","Do we need ID?","Can I use a dictionary?"],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["Bring a pencil.","Do we need ID?","Can I use a dictionary?"],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"Check required test materials.","type":"recording"}],"final_task":{"learner_instruction":"Check required test materials. Speak for at least 25 seconds.","minimum_seconds":25,"required_language":["Bring a pencil.","Do we need ID?"],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"Check required test materials.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T09_L02","lesson_number":2,"mission":"Identify what learners need for a test.","objectives":["Use key words and phrases to identify what learners need for a test.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on test materials.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to identify what learners need for a test.","examples":["Bring a pencil.","Do we need ID?","Can I use a dictionary?"],"pattern":"need; can","point":"need; can"}],"phrases":[{"audio_key":"a1_study_t09_l02_phrase_01","example":"Bring a pencil.","formality":"neutral","phrase":"Bring a pencil.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t09_l02_phrase_02","example":"Do we need ID?","formality":"neutral","phrase":"Do we need ID?","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t09_l02_phrase_03","example":"Can I use a dictionary?","formality":"neutral","phrase":"Can I use a dictionary?","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t09_l02_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Stress important instruction and rule words.","model":"Bring a pencil.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t09_l02_vocab_01","example":"I use the word ''pen'' in this lesson.","image_key":"a1_study_t09_l02_vocab_01","meaning":"A key word used in this lesson: pen.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''pen''.","word":"pen"},{"audio_key":"a1_study_t09_l02_vocab_02","example":"I use the word ''pencil'' in this lesson.","image_key":"a1_study_t09_l02_vocab_02","meaning":"A key word used in this lesson: pencil.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''pencil''.","word":"pencil"},{"audio_key":"a1_study_t09_l02_vocab_03","example":"I use the word ''paper'' in this lesson.","image_key":"a1_study_t09_l02_vocab_03","meaning":"A key word used in this lesson: paper.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''paper''.","word":"paper"},{"audio_key":"a1_study_t09_l02_vocab_04","example":"I use the word ''ID'' in this lesson.","image_key":"a1_study_t09_l02_vocab_04","meaning":"A key word used in this lesson: ID.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''ID''.","word":"ID"},{"audio_key":"a1_study_t09_l02_vocab_05","example":"I use the word ''dictionary'' in this lesson.","image_key":"a1_study_t09_l02_vocab_05","meaning":"A key word used in this lesson: dictionary.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''dictionary''.","word":"dictionary"}]},"title":"Test Materials"}'::jsonb, NOW(), NOW())
