VALUES ('0a72d24a-c8a2-5654-933c-3541420932e3', 'A1_STUDY_T10', 'Becoming an Independent Learner', 'A capstone A1 Study track that helps learners set goals, describe strengths and weaknesses, choose learning strategies, and speak independently about their progress.', 'en', 'A1', 'thematic', ARRAY['study']::text[], true, 10, '{"package":{"goal":"study","lesson_count":100,"level":"A1","package_id":"A1_STUDY_TRACKS_01_10","recommended_import_order":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"schema_version":"1.0.0","titles":["My First English Class","My Classroom","My School Life","Meeting Friends at School","My Study Day","Asking for Help","Studying Together","School Projects","Tests and Exams","Becoming an Independent Learner"],"track_count":10,"track_ids":["A1_STUDY_T01","A1_STUDY_T02","A1_STUDY_T03","A1_STUDY_T04","A1_STUDY_T05","A1_STUDY_T06","A1_STUDY_T07","A1_STUDY_T08","A1_STUDY_T09","A1_STUDY_T10"],"validation":"All files passed the uploaded JSON Schema using Draft 2020-12."},"track":{"analytics":{"events":["track_started","lesson_started","lesson_completed","speaking_attempted","speaking_passed","mission_attempted","mission_completed","track_completed","track_abandoned"],"mastery_metrics":["pronunciation_accuracy","fluency_score","grammar_accuracy","vocabulary_recall","listening_comprehension","response_relevance","confidence_score","completion_rate"]},"communication_outcome":"The learner can explain simple study goals, describe progress, ask for feedback, and speak for several minutes using supported A1 language.","completion_rules":{"maximum_attempts":null,"minimum_average_score":70,"minimum_lessons_completed":10,"required_final_mission":true,"speaking_pass_score":65},"description":"A capstone A1 Study track that helps learners set goals, describe strengths and weaknesses, choose learning strategies, and speak independently about their progress.","difficulty":{"cefr":"A1","speaking_target_seconds":240,"stage":"beginner","target_words_per_minute":63},"estimated_duration_minutes":120,"goal":"study","language_systems":{"discourse":["short question-answer exchanges","basic turn taking","simple repair strategies","sequencing short ideas"],"functions":["setting goals","describing progress","asking for feedback","making study plans"],"grammar":["Want to and need to","Can and cannot yet","Present simple review","Going to for plans"],"pronunciation":[{"description":"Clear, confident delivery in a longer A1 speaking task.","focus":"clarity","language_interference_notes":["Use clear English word order.","Do not drop important final consonants.","Avoid adding extra vowel sounds between consonants."]}],"vocabulary":{"core_phrases":["My goal is to speak English.","I want to understand movies.","I need English for study.","I can introduce myself.","I can read short texts.","I can ask simple questions.","I cannot speak fast yet.","Pronunciation is difficult for me.","I need more practice.","I learn by listening.","I repeat new phrases.","I review every day.","I use an app.","I watch short videos.","I write words in a notebook.","I study twenty minutes every day.","On Monday, I practice speaking.","This is my weekly plan.","Is my pronunciation clear?","What should I practice?"],"target_word_count":50,"themes":["goals","progress","strengths","weaknesses","learning strategies"]}},"learner_identity":"I can take responsibility for my English learning.","learning_objectives":[{"can_do_statement":"I can take responsibility for my English learning.","measurable_success":"Completes the final speaking mission for Becoming an Independent Learner.","objective_id":"OBJ_01","skill":"speaking"},{"can_do_statement":"I can understand short, clear English in this study situation.","measurable_success":"Answers at least 70 percent of listening checks correctly.","objective_id":"OBJ_02","skill":"listening"},{"can_do_statement":"I can use useful words and phrases in a short conversation.","measurable_success":"Uses target language in a multi-turn AI roleplay.","objective_id":"OBJ_03","skill":"interaction"},{"can_do_statement":"I can speak clearly enough for a patient listener to understand me.","measurable_success":"Achieves at least 65 on the speaking rubric.","objective_id":"OBJ_04","skill":"pronunciation"}],"level":"A1","prerequisites":["A1_STUDY_T09"],"progression":{"entry_ability":"The learner has completed the previous A1 Study track or demonstrates equivalent beginner ability.","exit_ability":"The learner can explain simple study goals, describe progress, ask for feedback, and speak for several minutes using supported A1 language.","next_track_unlocks":null,"spiral_review":["Want to and need to","Can and cannot yet","Present simple review","Going to for plans","goals","progress","strengths"]},"rewards":{"badge":{"badge_id":"BADGE_A1_STUDY_T10","description":"Completed the A1 Study track: Becoming an Independent Learner.","icon_key":"badge_a1_study_t10","name":"Independent Learner"},"certificate_eligible":true,"unlock_message":"You completed Becoming an Independent Learner and can now use English in this study situation.","xp":1000},"schema_version":"1.0.0","short_title":"Independent Learner","title":"Becoming an Independent Learner","track_id":"A1_STUDY_T10","track_number":10}}'::jsonb, NOW(), NOW())
