VALUES ('6a5296b0-1be7-53ad-8fec-8d5ce3f264b6', NULL, 'My English Goal', 'State a simple English learning goal.

The learner uses English in a realistic study situation focused on my english goal.', 0, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"My goal is to speak English.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["My goal is to speak English.","I want to understand movies.","I need English for study."],"points":10,"prompt":"Which phrase best helps you: state a simple english learning goal.","type":"multiple_choice"},{"answer":["My goal is to speak English.","I want to understand movies.","I need English for study."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["My goal is to speak English.","I want to understand movies.","I need English for study."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"State two clear learning goals.","type":"recording"}],"final_task":{"learner_instruction":"State two clear learning goals. Speak for at least 20 seconds.","minimum_seconds":20,"required_language":["My goal is to speak English.","I want to understand movies."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"State two clear learning goals.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T10_L01","lesson_number":1,"mission":"State a simple English learning goal.","objectives":["Use key words and phrases to state a simple english learning goal.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on my english goal.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to state a simple english learning goal.","examples":["My goal is to speak English.","I want to understand movies.","I need English for study."],"pattern":"want/need + to","point":"want/need + to"}],"phrases":[{"audio_key":"a1_study_t10_l01_phrase_01","example":"My goal is to speak English.","formality":"neutral","phrase":"My goal is to speak English.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t10_l01_phrase_02","example":"I want to understand movies.","formality":"neutral","phrase":"I want to understand movies.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t10_l01_phrase_03","example":"I need English for study.","formality":"neutral","phrase":"I need English for study.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t10_l01_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear, confident delivery in a longer A1 speaking task.","model":"My goal is to speak English.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t10_l01_vocab_01","example":"I use the word ''goal'' in this lesson.","image_key":"a1_study_t10_l01_vocab_01","meaning":"A key word used in this lesson: goal.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''goal''.","word":"goal"},{"audio_key":"a1_study_t10_l01_vocab_02","example":"I use the word ''speak'' in this lesson.","image_key":"a1_study_t10_l01_vocab_02","meaning":"A key word used in this lesson: speak.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''speak''.","word":"speak"},{"audio_key":"a1_study_t10_l01_vocab_03","example":"I use the word ''understand'' in this lesson.","image_key":"a1_study_t10_l01_vocab_03","meaning":"A key word used in this lesson: understand.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''understand''.","word":"understand"},{"audio_key":"a1_study_t10_l01_vocab_04","example":"I use the word ''improve'' in this lesson.","image_key":"a1_study_t10_l01_vocab_04","meaning":"A key word used in this lesson: improve.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''improve''.","word":"improve"},{"audio_key":"a1_study_t10_l01_vocab_05","example":"I use the word ''learn'' in this lesson.","image_key":"a1_study_t10_l01_vocab_05","meaning":"A key word used in this lesson: learn.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''learn''.","word":"learn"}]},"title":"My English Goal"}'::jsonb, NOW(), NOW())
