INSERT INTO courses.lessons (id, module_id, title, description, order_index, source_metadata, created_at, updated_at)
VALUES ('85bfb3c4-a675-5dea-8e28-c80bc56528f2', NULL, 'My Next Step', 'Make a simple future learning plan.

The learner uses English in a realistic study situation focused on my next step.', 8, '{"adaptive_learning":{"easy_path":["Remove sentence frames and add one unscripted follow-up question."],"review_triggers":[{"action":"Repeat pronunciation, controlled speaking, and guided dialogue before retrying.","condition":"Speaking score is below 65."},{"action":"Replay the model at slower speed with highlighted transcript support.","condition":"Listening accuracy is below 70."}],"standard_path":["Use visual support, model audio, guided dialogue, and the standard AI mission."],"support_path":["Show translations, keep sentence frames visible, slow audio to 0.75 speed, and allow phrase-by-phrase repetition."]},"assessment":{"checks":[{"answer":"I am going to practice every day.","explanation":"This phrase directly supports the lesson mission.","item_id":"Q_01","options":["I am going to practice every day.","My next target is A2.","I will continue learning."],"points":10,"prompt":"Which phrase best helps you: make a simple future learning plan.","type":"multiple_choice"},{"answer":["I am going to practice every day.","My next target is A2.","I will continue learning."],"explanation":"The phrases follow the lesson''s communication sequence.","item_id":"Q_02","options":["I am going to practice every day.","My next target is A2.","I will continue learning."],"points":10,"prompt":"Put the short conversation in a logical order.","type":"ordering"},{"answer":"Learner recording scored by the speaking engine.","explanation":"Score task completion, intelligibility, and target-language use.","item_id":"Q_03","points":30,"prompt":"State three next steps.","type":"recording"}],"final_task":{"learner_instruction":"State three next steps. Speak for at least 60 seconds.","minimum_seconds":60,"required_language":["I am going to practice every day.","My next target is A2."],"rubric":[{"criterion":"task_completion","pass_description":"The learner completes the communication goal.","weight":0.4},{"criterion":"intelligibility","pass_description":"The learner is understandable to a patient listener.","weight":0.25},{"criterion":"vocabulary","pass_description":"The learner uses at least two target words or phrases.","weight":0.2},{"criterion":"confidence","pass_description":"The learner attempts the task without abandoning it.","weight":0.15}],"scenario":"State three next steps.","task_type":"ai_conversation"},"pass_score":65},"content_safety":{"age_rating":"all_ages","sensitive_topics":[]},"duration_minutes":12,"lesson_id":"A1_STUDY_T10_L09","lesson_number":9,"mission":"Make a simple future learning plan.","objectives":["Use key words and phrases to make a simple future learning plan.","Understand a short beginner-level model conversation.","Complete a spoken mission with understandable English."],"rewards":{"bonus_condition":"Complete the final mission on the first attempt.","bonus_xp":25,"streak_credit":true,"xp":100},"scenario":"The learner uses English in a realistic study situation focused on my next step.","target_language":{"grammar":[{"common_errors":["Using the wrong word order.","Leaving out a necessary verb or helper word."],"communicative_use":"Use this pattern to make a simple future learning plan.","examples":["I am going to practice every day.","My next target is A2.","I will continue learning."],"pattern":"going to; will chunks","point":"going to; will chunks"}],"phrases":[{"audio_key":"a1_study_t10_l09_phrase_01","example":"I am going to practice every day.","formality":"neutral","phrase":"I am going to practice every day.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t10_l09_phrase_02","example":"My next target is A2.","formality":"neutral","phrase":"My next target is A2.","use_case":"Use this phrase to complete the lesson''s speaking mission."},{"audio_key":"a1_study_t10_l09_phrase_03","example":"I will continue learning.","formality":"neutral","phrase":"I will continue learning.","use_case":"Use this phrase to complete the lesson''s speaking mission."}],"pronunciation":[{"audio_key":"a1_study_t10_l09_pronunciation_01","common_error":"Speaking word by word with unclear stress.","focus":"Clear, confident delivery in a longer A1 speaking task.","model":"I am going to practice every day.","tip":"Listen, pause, and repeat in one clear thought group."}],"vocabulary":[{"audio_key":"a1_study_t10_l09_vocab_01","example":"I use the word ''next'' in this lesson.","image_key":"a1_study_t10_l09_vocab_01","meaning":"A key word used in this lesson: next.","part_of_speech":"noun","simple_definition":"A simple A1 meaning for ''next''.","word":"next"},{"audio_key":"a1_study_t10_l09_vocab_02","example":"I use the word ''continue'' in this lesson.","image_key":"a1_study_t10_l09_vocab_02","meaning":"A key word used in this lesson: continue.","part_of_speech":"verb","simple_definition":"A simple A1 meaning for ''continue''.","word":"continue"},{"audio_key":"a1_study_t10_l09_vocab_03","example":"I use the word ''going'' in this lesson.","image_key":"a1_study_t10_l09_vocab_03","meaning":"A key word used in this lesson: going.","part_of_speech":"adjective","simple_definition":"A simple A1 meaning for ''going''.","word":"going"},{"audio_key":"a1_study_t10_l09_vocab_04","example":"I use the word ''practice'' in this lesson.","image_key":"a1_study_t10_l09_vocab_04","meaning":"A key word used in this lesson: practice.","part_of_speech":"adverb","simple_definition":"A simple A1 meaning for ''practice''.","word":"practice"},{"audio_key":"a1_study_t10_l09_vocab_05","example":"I use the word ''target'' in this lesson.","image_key":"a1_study_t10_l09_vocab_05","meaning":"A key word used in this lesson: target.","part_of_speech":"expression","simple_definition":"A simple A1 meaning for ''target''.","word":"target"}]},"title":"My Next Step"}'::jsonb, NOW(), NOW())
